pub(crate) use rowenc::{MAX_COLUMNS, MAX_RELATION_COLUMNS};

const COLUMN_SET_WORDS: usize = MAX_COLUMNS.div_ceil(u64::BITS as usize);

/// A fixed-width set of physical relation attributes. PostgreSQL numbers
/// ordinary attributes from one; callers use the corresponding zero-based
/// physical column index here. Keeping this type at catalog, DML, and replay
/// boundaries prevents a wider relation from being truncated to one machine
/// word.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ColumnSet {
    words: [u64; COLUMN_SET_WORDS],
}

impl ColumnSet {
    pub(crate) const ENCODED_BYTES: usize = COLUMN_SET_WORDS * core::mem::size_of::<u64>();
    pub(crate) const EMPTY: Self = Self {
        words: [0; COLUMN_SET_WORDS],
    };

    pub(crate) const fn from_low_word(word: u64) -> Self {
        let mut set = Self::EMPTY;
        set.words[0] = word;
        set
    }

    pub(crate) fn all(columns: usize) -> Self {
        debug_assert!(columns <= MAX_COLUMNS);
        let mut set = Self::EMPTY;
        for column in 0..columns {
            set.insert(column);
        }
        set
    }

    pub(crate) fn from_column(column: usize) -> Self {
        let mut set = Self::EMPTY;
        set.insert(column);
        set
    }

    pub(crate) fn insert(&mut self, column: usize) {
        debug_assert!(column < MAX_COLUMNS);
        self.words[column / u64::BITS as usize] |= 1u64 << (column % u64::BITS as usize);
    }

    pub(crate) const fn contains(&self, column: usize) -> bool {
        column < MAX_COLUMNS
            && self.words[column / u64::BITS as usize] & (1u64 << (column % u64::BITS as usize))
                != 0
    }

    pub(crate) fn intersects(self, other: Self) -> bool {
        self.words
            .iter()
            .zip(other.words)
            .any(|(left, right)| left & right != 0)
    }

    pub(crate) const fn is_empty(self) -> bool {
        let mut index = 0;
        while index < COLUMN_SET_WORDS {
            if self.words[index] != 0 {
                return false;
            }
            index += 1;
        }
        true
    }

    pub(crate) fn count_ones(self) -> u32 {
        self.words.iter().map(|word| word.count_ones()).sum()
    }

    pub(crate) fn first(self) -> Option<usize> {
        self.words
            .iter()
            .copied()
            .enumerate()
            .find_map(|(word, bits)| {
                (bits != 0).then_some(word * u64::BITS as usize + bits.trailing_zeros() as usize)
            })
    }

    pub(crate) fn union_with(&mut self, other: Self) {
        for (target, source) in self.words.iter_mut().zip(other.words) {
            *target |= source;
        }
    }

    pub(crate) fn difference(self, other: Self) -> Self {
        let mut result = self;
        for (target, removed) in result.words.iter_mut().zip(other.words) {
            *target &= !removed;
        }
        result
    }

    pub(crate) const fn words(&self) -> &[u64; COLUMN_SET_WORDS] {
        &self.words
    }

    pub(crate) fn set_word(&mut self, index: usize, word: u64) -> bool {
        let Some(target) = self.words.get_mut(index) else {
            return false;
        };
        *target = word;
        true
    }
}

impl core::fmt::Display for ColumnSet {
    fn fmt(&self, formatter: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        if self.words[1..].iter().all(|word| *word == 0) {
            return self.words[0].fmt(formatter);
        }
        formatter.write_str("x")?;
        let mut separator = "";
        for (index, word) in self.words.iter().copied().enumerate() {
            if word == 0 {
                continue;
            }
            write!(formatter, "{separator}{index:x}:{word:x}")?;
            separator = ",";
        }
        Ok(())
    }
}

impl core::str::FromStr for ColumnSet {
    type Err = core::num::ParseIntError;

    fn from_str(source: &str) -> Result<Self, Self::Err> {
        if let Some(encoded) = source.strip_prefix('x') {
            let mut result = Self::EMPTY;
            for entry in encoded.split(',') {
                let (index, word) = entry.split_once(':').unwrap_or(("", ""));
                let index = usize::from_str_radix(index, 16)?;
                let word = u64::from_str_radix(word, 16)?;
                if index >= COLUMN_SET_WORDS {
                    return "".parse::<u64>().map(|_| result);
                }
                result.words[index] = word;
            }
            Ok(result)
        } else {
            source.parse::<u64>().map(Self::from_low_word)
        }
    }
}

impl core::ops::BitOrAssign for ColumnSet {
    fn bitor_assign(&mut self, rhs: Self) {
        self.union_with(rhs);
    }
}

impl core::ops::BitOr for ColumnSet {
    type Output = Self;

    fn bitor(mut self, rhs: Self) -> Self::Output {
        self |= rhs;
        self
    }
}

/// Maximum explicit relation membership entries in one publication.  WAL
/// encodes this count in one byte, so the capacity derives from that boundary
/// instead of permitting an unencodable 256th member.
pub(crate) const MAX_PUBLICATION_TABLES: usize = u8::MAX as usize;
/// One publication's filters live inline in its fixed catalog record.  The
/// bound keeps catalog and WAL decode frames comfortably below the server's
/// bounded-stack contract while still accepting the simple predicates that
/// PostgreSQL permits here.
pub(crate) const PUBLICATION_FILTER_SQL_MAX: usize = 64;
/// Total filter-source storage for one publication. Individual filters retain
/// their own SQL boundary above; this shared storage avoids reserving that
/// boundary for every unused relation member.
pub(crate) const PUBLICATION_FILTER_STORAGE_BYTES: usize = 512;

#[derive(Clone, Copy, Debug)]
pub struct PublicationFilters {
    sql: StackStr<PUBLICATION_FILTER_STORAGE_BYTES>,
    ends: [u16; MAX_PUBLICATION_TABLES],
}

impl PublicationFilters {
    pub(crate) const EMPTY: Self = Self {
        sql: StackStr::new(),
        ends: [0; MAX_PUBLICATION_TABLES],
    };

    pub(crate) fn from_sql(
        filters: &[StackStr<PUBLICATION_FILTER_SQL_MAX>],
    ) -> Result<Self, SqlError> {
        let mut out = Self::EMPTY;
        for (index, filter) in filters.iter().enumerate() {
            let before = out.sql.as_str().len();
            use core::fmt::Write;
            let _ = out.sql.write_str(filter.as_str());
            if out.sql.is_truncated() {
                return Err(sql_err!(
                    sqlstate::PROGRAM_LIMIT_EXCEEDED,
                    "publication row filters exceed {} bytes",
                    PUBLICATION_FILTER_STORAGE_BYTES
                ));
            }
            out.ends[index] = (before + filter.as_str().len()) as u16;
        }
        Ok(out)
    }

    pub(crate) fn get(&self, index: usize) -> &str {
        let start = if index == 0 {
            0
        } else {
            self.ends[index - 1] as usize
        };
        &self.sql.as_str()[start..self.ends[index] as usize]
    }

    pub(crate) fn materialize_sql(
        &self,
        count: usize,
    ) -> [StackStr<PUBLICATION_FILTER_SQL_MAX>; MAX_PUBLICATION_TABLES] {
        let mut filters = [StackStr::new(); MAX_PUBLICATION_TABLES];
        for (index, filter) in filters[..count].iter_mut().enumerate() {
            *filter = StackStr::from_str(self.get(index));
        }
        filters
    }
}

/// Inline durable definition lists carry at most this many items. Constraint
/// positions also determine catalog and trigger OIDs; changing this stride
/// requires checking identity ranges and the durable representation.
/// Wider DDL is rejected before catalog mutation.
pub(crate) const MAX_DEFINITION_ITEMS: usize = 64;
/// Nested row-state walk cursors (spill-merge recursion during DML) lease
/// from this startup-sized pool.
pub(crate) const MAX_ROW_WALK_NESTING: usize = 64;

/// A subscription's publication list is part of its startup-bounded durable
/// state, rather than an unbounded connection-side string.
pub(crate) const MAX_SUBSCRIPTION_PUBLICATIONS: usize = MAX_DEFINITION_ITEMS;
pub(crate) const SUBSCRIPTION_CONNINFO_BYTES: usize = 512;
pub(crate) const MAX_TRIGGER_ARGUMENTS: usize = MAX_DEFINITION_ITEMS;
pub(crate) const TRIGGER_ARGUMENT_BYTES: usize = u8::MAX as usize;
pub(crate) const LARGE_OBJECT_BLOCK_SIZE: usize = 2_048;
pub(crate) const INTERNAL_LARGE_OBJECT_SCHEMA: &str = "pos3ql_internal";
pub(crate) const INTERNAL_LARGE_OBJECT_TABLE: &str = "large_object_pages";

/// Physical table slots include the internal large-object page relation after
/// all configured user-table slots.
pub(crate) const fn table_slot_capacity(config: &Config) -> usize {
    config.max_tables + 1
}

/// A bounded trigger invocation argument vector.  SQL parses the literals once
/// before catalog mutation; WAL and checkpoints carry the same typed state.
#[derive(Debug, Clone, Copy)]
pub(crate) struct TriggerArguments {
    values: [StackStr<TRIGGER_ARGUMENT_BYTES>; MAX_TRIGGER_ARGUMENTS],
    count: u8,
}

impl TriggerArguments {
    pub(crate) const EMPTY: Self = Self {
        values: [StackStr::new(); MAX_TRIGGER_ARGUMENTS],
        count: 0,
    };

    pub(crate) fn parse(values: &[&str]) -> Result<Self, SqlError> {
        if values.len() > MAX_TRIGGER_ARGUMENTS {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "too many trigger arguments (limit {})",
                MAX_TRIGGER_ARGUMENTS
            ));
        }
        let mut out = Self::EMPTY;
        for (index, value) in values.iter().enumerate() {
            if value.as_bytes().contains(&0) {
                return Err(sql_err!(
                    sqlstate::INVALID_PARAMETER_VALUE,
                    "trigger argument contains NUL byte"
                ));
            }
            let parsed = StackStr::from_str(value);
            if parsed.is_truncated() {
                return Err(sql_err!(
                    sqlstate::PROGRAM_LIMIT_EXCEEDED,
                    "trigger argument exceeds {} bytes",
                    TRIGGER_ARGUMENT_BYTES
                ));
            }
            out.values[index] = parsed;
        }
        out.count = values.len() as u8;
        Ok(out)
    }

    pub(crate) fn values(&self) -> &[StackStr<TRIGGER_ARGUMENT_BYTES>] {
        &self.values[..usize::from(self.count)]
    }
}

/// A live subscription's bounded, nonempty connection-info value. SQL and WAL
/// construct this before durable catalog state changes; the empty value is
/// reserved for an absent catalog slot.
#[derive(Clone, Copy)]
pub(crate) struct SubscriptionConnInfo {
    text: StackStr<SUBSCRIPTION_CONNINFO_BYTES>,
    endpoint: Option<ConnectionInfo>,
}

impl SubscriptionConnInfo {
    const EMPTY: Self = Self {
        text: StackStr::new(),
        endpoint: None,
    };

    pub(crate) fn parse(value: &str) -> Result<Self, SqlError> {
        if value.is_empty() || value.as_bytes().contains(&0) {
            return Err(sql_err!(
                sqlstate::INVALID_PARAMETER_VALUE,
                "subscription connection string must be nonempty and contain no NUL byte"
            ));
        }
        let value = StackStr::from_str(value);
        if value.is_truncated() {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "subscription connection string exceeds {} bytes",
                SUBSCRIPTION_CONNINFO_BYTES
            ));
        }
        crate::pg::replication_client::validate_connection_syntax(value.as_str())
            .map_err(subscription_conninfo_error)?;
        // A disabled PostgreSQL subscription may contain connection settings
        // that this server never opens. Keep its validated catalog spelling;
        // an enabled subscription must prove a usable bounded endpoint below.
        let endpoint = ConnectionInfo::parse(value.as_str()).ok();
        Ok(Self {
            text: value,
            endpoint,
        })
    }

    pub(crate) fn as_str(&self) -> &str {
        self.text.as_str()
    }

    /// Resolves PostgreSQL's documented subscription `application_name`
    /// default while the catalog identity is still available.  Workers receive
    /// only this complete transport contract.
    pub(crate) fn endpoint_for(
        &self,
        subscription: SqlName,
    ) -> Option<crate::pg::replication_client::SubscriptionEndpoint> {
        self.endpoint.map(|endpoint| {
            crate::pg::replication_client::SubscriptionEndpoint::resolve(endpoint, subscription)
        })
    }

    pub(crate) fn require_endpoint_for(
        &self,
        subscription: SqlName,
    ) -> Result<crate::pg::replication_client::SubscriptionEndpoint, SqlError> {
        self.endpoint_for(subscription).ok_or_else(|| {
            sql_err!(
                sqlstate::INVALID_PARAMETER_VALUE,
                "enabled subscription connection string requires a numeric host, port, user, dbname, and sslmode"
            )
        })
    }
}

fn subscription_conninfo_error(error: ConnectionInfoError) -> SqlError {
    let message = match error {
        ConnectionInfoError::Missing(field) => {
            return sql_err!(
                sqlstate::INVALID_PARAMETER_VALUE,
                "subscription connection string requires {}",
                field
            );
        }
        ConnectionInfoError::Duplicate => "subscription connection string repeats an option",
        ConnectionInfoError::InvalidValue => {
            "subscription connection string contains an invalid value"
        }
        ConnectionInfoError::InvalidPort => "subscription connection string has an invalid port",
        ConnectionInfoError::NonNumericHost => {
            "subscription connection string requires a numeric host address"
        }
        ConnectionInfoError::UnsupportedOption => {
            "subscription connection string contains an unsupported option"
        }
        ConnectionInfoError::UnsupportedSslMode => {
            "subscription connection string has an unsupported sslmode"
        }
        ConnectionInfoError::Limit => "subscription connection string value exceeds its limit",
        ConnectionInfoError::Syntax => "subscription connection string has invalid syntax",
    };
    sql_err!(sqlstate::INVALID_PARAMETER_VALUE, "{}", message)
}

/// Rows handed from the durable merge cursor to the executor. The fixed batch
/// boundary lets one resident SST block feed a bounded scan step rather than
/// crossing the storage/executor seam once per row.
#[derive(Clone, Copy)]
pub(crate) struct SpilledRow<'a> {
    pub(crate) rowid: u64,
    pub(crate) representation: SpilledRowRepresentation<'a>,
}

/// The physical representation a merged spill cursor hands to the executor.
/// Canonical entries retain the historical path; PAX entries arrive as
/// arena-owned decoded values after the resident block has been released.
#[derive(Clone, Copy)]
pub(crate) enum SpilledRowRepresentation<'a> {
    Encoded(&'a [u8]),
    Values(&'a [Datum<'a>]),
}

/// Key and payload borrow one caller-owned scratch row for the callback only.
pub(crate) struct CheckpointValueEntry<'a> {
    pub(crate) rowid: u64,
    pub(crate) commit_lsn: u64,
    pub(crate) hash: u64,
    pub(crate) key: &'a [u8],
    pub(crate) payload: &'a [u8],
}

/// A scan batch is deliberately small enough to leave statement-arena space
/// for joins and expression results, while amortizing the cold cursor seam.
pub(crate) const SPILL_SCAN_BATCH_ROWS: usize = 128;

type SpilledRowBatchVisitor<'a, 'callback> =
    dyn FnMut(&[SpilledRow<'a>]) -> Result<core::ops::ControlFlow<()>, SqlError> + 'callback;

fn spill_read_error(error: crate::store::SstError) -> SqlError {
    match error {
        crate::store::SstError::Store(crate::store::StoreError::NotReady) => {
            sql_err!(sqlstate::INTERNAL_IO_WAIT, "durable block read in progress")
        }
        other => sql_err!(sqlstate::IO_ERROR, "spill read: {:?}", other),
    }
}

fn value_index_read_error(error: crate::store::ValueIndexError) -> SqlError {
    match error {
        crate::store::ValueIndexError::Store(crate::store::StoreError::NotReady) => {
            sql_err!(
                sqlstate::INTERNAL_IO_WAIT,
                "durable value-index read in progress"
            )
        }
        other => sql_err!(
            sqlstate::IO_ERROR,
            "persistent value-index read: {:?}",
            other
        ),
    }
}

/// An SQL identifier, owned inline. PostgreSQL caps names at 63 bytes
/// (NAMEDATALEN - 1); so does this.
#[derive(Clone, Copy, PartialEq, Eq)]
pub struct SqlName {
    len: u8,
    bytes: [u8; 63],
}

impl SqlName {
    /// A zero-length name, for statically initializing arrays of names.
    pub const EMPTY: Self = SqlName {
        len: 0,
        bytes: [0u8; 63],
    };

    pub fn parse(s: &str) -> Result<Self, SqlError> {
        if s.len() > 63 {
            // PostgreSQL truncates with a notice; failing loudly is safer.
            return Err(sql_err!(
                crate::sql::eval::sqlstate::NAME_TOO_LONG,
                "name \"{}\" is longer than 63 bytes",
                s
            ));
        }
        let mut bytes = [0u8; 63];
        bytes[..s.len()].copy_from_slice(s.as_bytes());
        Ok(Self {
            len: s.len() as u8,
            bytes,
        })
    }

    pub fn as_str(&self) -> &str {
        unsafe { core::str::from_utf8_unchecked(&self.bytes[..self.len as usize]) }
    }
}

/// A replication-slot name already proven to satisfy PostgreSQL's portable
/// `[a-z0-9_]{1,63}` boundary. Keeping it distinct from an SQL identifier
/// prevents quoted or catalog-recovered names from bypassing that contract.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) struct ReplicationSlotName(SqlName);

impl ReplicationSlotName {
    pub(crate) fn parse(value: &str) -> Result<Self, SqlError> {
        if value.is_empty()
            || value.len() > 63
            || !value
                .bytes()
                .all(|byte| byte.is_ascii_lowercase() || byte.is_ascii_digit() || byte == b'_')
        {
            return Err(sql_err!(
                sqlstate::INVALID_NAME,
                "invalid replication slot name \"{}\"",
                value
            ));
        }
        Ok(Self(SqlName::parse(value)?))
    }

    pub(crate) const fn sql_name(self) -> SqlName {
        self.0
    }

    pub(crate) fn as_str(&self) -> &str {
        self.0.as_str()
    }
}

impl Hash for SqlName {
    fn hash<H: Hasher>(&self, state: &mut H) {
        self.as_str().hash(state);
    }
}

impl core::fmt::Debug for SqlName {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        core::fmt::Debug::fmt(self.as_str(), f)
    }
}

/// A small owned constant, storable in the catalog (column defaults).
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum OwnedDatum {
    Null,
    Bool(bool),
    Char(u8),
    Int4(i32),
    Oid(u32),
    Tid(crate::sql::types::Tid),
    Cid(u32),
    Xid8(u64),
    Snapshot {
        legacy: bool,
        len: u8,
        bytes: [u8; MAX_DEFAULT_TEXT],
    },
    PgLsn(u64),
    AclItem {
        len: u8,
        bytes: [u8; MAX_DEFAULT_TEXT],
    },
    Money(i64),
    Int8(i64),
    Regtype {
        referenced_oid: i32,
        len: u8,
        bytes: [u8; MAX_DEFAULT_TEXT],
    },
    RegObject {
        kind: RegObjectType,
        referenced_oid: i32,
        len: u8,
        bytes: [u8; MAX_DEFAULT_TEXT],
    },
    Float8(f64),
    Text {
        len: u8,
        bytes: [u8; MAX_DEFAULT_TEXT],
    },
    PgNodeTree {
        len: u8,
        bytes: [u8; MAX_DEFAULT_TEXT],
    },
    Geometry {
        kind: crate::sql::types::GeometryKind,
        len: u8,
        bytes: [u8; MAX_DEFAULT_TEXT],
    },
    TextSearch {
        query: bool,
        len: u8,
        bytes: [u8; MAX_DEFAULT_TEXT],
    },
    Numeric {
        sign: u8,
        weight: i16,
        dscale: u16,
        nbytes: u8,
        digits: [u8; MAX_DEFAULT_TEXT],
    },
    Date(i32),
    Timestamp(i64),
    Timestamptz(i64),
    Time(i64),
    Timetz(i64, i32),
    Interval(crate::sql::types::Interval),
    Json {
        jsonb: bool,
        len: u8,
        bytes: [u8; MAX_DEFAULT_TEXT],
    },
    JsonPath {
        len: u8,
        bytes: [u8; MAX_DEFAULT_TEXT],
    },
    Array {
        element: CachedArrayElement,
        len: u8,
        bytes: [u8; MAX_DEFAULT_TEXT],
    },
    Int2Vector {
        lower_bound: i32,
        len: u8,
        bytes: [u8; MAX_DEFAULT_TEXT],
    },
    OidVector {
        lower_bound: i32,
        len: u8,
        bytes: [u8; MAX_DEFAULT_TEXT],
    },
    Range {
        kind: crate::sql::types::RangeKind,
        multirange: bool,
        len: u8,
        bytes: [u8; MAX_DEFAULT_TEXT],
    },
    Bit {
        varying: bool,
        len: u8,
        bytes: [u8; MAX_DEFAULT_TEXT],
    },
    Uuid([u8; 16]),
    Bytea {
        len: u8,
        bytes: [u8; MAX_DEFAULT_TEXT],
    },
    Inet(crate::sql::net::NetAddr),
    Cidr(crate::sql::net::NetAddr),
    Macaddr([u8; 6]),
    Macaddr8([u8; 8]),
    Enum {
        slot: TypeCreation,
        member: Option<crate::sql::types::EnumMemberId>,
        sort: f64,
        label: SqlName,
    },
}

/// PostgreSQL's object-reference types; an arbitrary OID is not a type tag.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(u8)]
pub enum RegObjectType {
    Regproc,
    Regprocedure,
    Regoper,
    Regoperator,
    Regclass,
    Regnamespace,
    Regrole,
    Regconfig,
    Regdictionary,
    Regcollation,
}

impl RegObjectType {
    pub(crate) fn from_oid(oid: i32) -> Option<Self> {
        Some(match ColType::from_oid(oid)? {
            ColType::Regproc => Self::Regproc,
            ColType::Regprocedure => Self::Regprocedure,
            ColType::Regoper => Self::Regoper,
            ColType::Regoperator => Self::Regoperator,
            ColType::Regclass => Self::Regclass,
            ColType::Regnamespace => Self::Regnamespace,
            ColType::Regrole => Self::Regrole,
            ColType::Regconfig => Self::Regconfig,
            ColType::Regdictionary => Self::Regdictionary,
            ColType::Regcollation => Self::Regcollation,
            _ => return None,
        })
    }

    pub(crate) fn oid(self) -> i32 {
        match self {
            Self::Regproc => ColType::Regproc,
            Self::Regprocedure => ColType::Regprocedure,
            Self::Regoper => ColType::Regoper,
            Self::Regoperator => ColType::Regoperator,
            Self::Regclass => ColType::Regclass,
            Self::Regnamespace => ColType::Regnamespace,
            Self::Regrole => ColType::Regrole,
            Self::Regconfig => ColType::Regconfig,
            Self::Regdictionary => ColType::Regdictionary,
            Self::Regcollation => ColType::Regcollation,
        }
        .oid()
    }
}

/// Fixed catalog capacity for a parsed default value. It matches the bounded
/// SQL source capacity, so a supported literal cannot become unrepresentable
/// merely because its typed form takes a few more bytes.
pub(crate) const MAX_DEFAULT_TEXT: usize = DEFAULT_EXPR_MAX;

/// The complete default state of one column.
///
/// A constant retains its parsed value as an execution cache and its source as
/// catalog identity. Keeping the alternatives together prevents a column from
/// being both generated and defaulted, or from carrying a value without the
/// expression that describes it.
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum ColumnDefault {
    None,
    Constant {
        value: OwnedDatum,
        expression: StackStr<DEFAULT_EXPR_MAX>,
    },
    Expression(StackStr<DEFAULT_EXPR_MAX>),
    Generated {
        expression: StackStr<DEFAULT_EXPR_MAX>,
        kind: Generation,
    },
}

/// How a generated column holds its value. PostgreSQL 18 computes a
/// `VIRTUAL` column when it is read and keeps a `STORED` one in the row. A
/// generation expression reads only its own row and is immutable, so pos3ql
/// keeps both kinds' values in the row; the kind decides what PostgreSQL
/// exposes (`attgenerated`, trigger rows, error details) and which
/// definitions are allowed.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Generation {
    Stored,
    Virtual,
}

impl Generation {
    /// `pg_attribute.attgenerated`.
    pub const fn code(self) -> u8 {
        match self {
            Self::Stored => b's',
            Self::Virtual => b'v',
        }
    }

    pub const fn from_code(code: u8) -> Option<Self> {
        match code {
            b's' => Some(Self::Stored),
            b'v' => Some(Self::Virtual),
            _ => None,
        }
    }
}

impl ColumnDefault {
    pub const NONE: Self = Self::None;

    pub const fn expression(&self) -> Option<&StackStr<DEFAULT_EXPR_MAX>> {
        match self {
            Self::None => None,
            Self::Constant { expression, .. }
            | Self::Expression(expression)
            | Self::Generated { expression, .. } => Some(expression),
        }
    }

    pub const fn constant(&self) -> Option<&OwnedDatum> {
        match self {
            Self::Constant { value, .. } => Some(value),
            Self::None | Self::Expression(_) | Self::Generated { .. } => None,
        }
    }

    pub const fn is_generated(self) -> bool {
        matches!(self, Self::Generated { .. })
    }

    /// The generation kind of a generated column.
    pub const fn generation(self) -> Option<Generation> {
        match self {
            Self::Generated { kind, .. } => Some(kind),
            _ => None,
        }
    }

    pub const fn is_virtual(self) -> bool {
        matches!(
            self,
            Self::Generated {
                kind: Generation::Virtual,
                ..
            }
        )
    }

    pub const fn from_parts(
        value: Option<OwnedDatum>,
        expression: Option<StackStr<DEFAULT_EXPR_MAX>>,
        generation: Option<Generation>,
    ) -> Option<Self> {
        match (value, expression, generation) {
            (None, None, None) => Some(Self::None),
            (Some(value), Some(expression), None) => Some(Self::Constant { value, expression }),
            (Some(_), None, None) => None,
            (None, Some(expression), None) => Some(Self::Expression(expression)),
            (None, Some(expression), Some(kind)) => Some(Self::Generated { expression, kind }),
            _ => None,
        }
    }
}

impl OwnedDatum {
    pub fn from_datum(d: &crate::sql::types::Datum) -> Result<Self, SqlError> {
        use crate::sql::types::Datum;
        Ok(match d {
            Datum::Record(_) | Datum::Composite { .. } | Datum::CompositeText { .. } => {
                return Err(sql_err!(
                    sqlstate::FEATURE_NOT_SUPPORTED,
                    "cannot store a composite (record) value in a column"
                ));
            }
            Datum::PgDdlCommand => {
                return Err(sql_err!(
                    sqlstate::FEATURE_NOT_SUPPORTED,
                    "cannot store a pseudo-type value in a column"
                ));
            }
            Datum::PgNodeTree(node) => {
                let (len, bytes) = Self::bytes(node.as_str().as_bytes(), "pg_node_tree")?;
                Self::PgNodeTree { len, bytes }
            }
            Datum::Int2Vector { raw, lower_bound } => {
                let (len, bytes) = Self::bytes(raw, "int2vector")?;
                Self::Int2Vector {
                    lower_bound: *lower_bound,
                    len,
                    bytes,
                }
            }
            Datum::OidVector { raw, lower_bound } => {
                let (len, bytes) = Self::bytes(raw, "oidvector")?;
                Self::OidVector {
                    lower_bound: *lower_bound,
                    len,
                    bytes,
                }
            }
            Datum::Regtype {
                referenced_oid,
                name,
            } => {
                let (len, bytes) = Self::bytes(name.as_bytes(), "regtype")?;
                Self::Regtype {
                    referenced_oid: *referenced_oid,
                    len,
                    bytes,
                }
            }
            Datum::RegObject {
                type_oid,
                referenced_oid,
                name,
            } => {
                let (len, bytes) = Self::bytes(name.as_bytes(), "catalog object")?;
                Self::RegObject {
                    kind: RegObjectType::from_oid(*type_oid).ok_or_else(|| {
                        sql_err!(
                            sqlstate::DATATYPE_MISMATCH,
                            "invalid object-reference default type"
                        )
                    })?,
                    referenced_oid: *referenced_oid,
                    len,
                    bytes,
                }
            }
            Datum::Null => Self::Null,
            Datum::Bool(b) => Self::Bool(*b),
            Datum::Char(byte) => Self::Char(*byte),
            Datum::Int4(v) => Self::Int4(*v),
            Datum::Oid(v) => Self::Oid(*v),
            Datum::Tid(v) => Self::Tid(*v),
            Datum::Cid(v) => Self::Cid(*v),
            Datum::Xid8(v) => Self::Xid8(*v),
            Datum::Snapshot { value, legacy } => {
                let (len, bytes) = Self::bytes(value.raw(), "transaction snapshot")?;
                Self::Snapshot {
                    legacy: *legacy,
                    len,
                    bytes,
                }
            }
            Datum::PgLsn(v) => Self::PgLsn(*v),
            Datum::AclItem(item) => {
                let (len, bytes) = Self::bytes(item.raw(), "aclitem")?;
                Self::AclItem { len, bytes }
            }
            Datum::Money(v) => Self::Money(*v),
            Datum::Int2(v) => Self::Int4(*v as i32),
            Datum::Int8(v) => Self::Int8(*v),
            // Widened like int2→int4; the column re-coerces the default back to
            // real (f64→f32 is lossless for a value that was already f32).
            Datum::Float4(v) => Self::Float8(f64::from(*v)),
            Datum::Float8(v) => Self::Float8(*v),
            Datum::Date(value) => Self::Date(*value),
            Datum::Timestamp(value) => Self::Timestamp(*value),
            Datum::Timestamptz(value) => Self::Timestamptz(*value),
            Datum::Time(value) => Self::Time(*value),
            Datum::Timetz(time, zone) => Self::Timetz(*time, *zone),
            Datum::Interval(value) => Self::Interval(*value),
            Datum::Uuid(value) => Self::Uuid(*value),
            Datum::Json { text, jsonb } => Self::json(*jsonb, text)?,
            Datum::Xml(text) => {
                let (len, bytes) = Self::bytes(text.as_bytes(), "xml")?;
                Self::Text { len, bytes }
            }
            Datum::JsonPath(text) => {
                let (len, bytes) = Self::bytes(text.as_bytes(), "jsonpath")?;
                Self::JsonPath { len, bytes }
            }
            Datum::TsVector(text) => {
                let (len, bytes) = Self::bytes(text.as_bytes(), "text-search")?;
                Self::TextSearch {
                    query: false,
                    len,
                    bytes,
                }
            }
            Datum::TsQuery(text) => {
                let (len, bytes) = Self::bytes(text.as_bytes(), "text-search")?;
                Self::TextSearch {
                    query: true,
                    len,
                    bytes,
                }
            }
            Datum::Array { element, raw } => Self::array(*element, raw)?,
            Datum::Range { text, kind } => Self::range(*kind, false, text)?,
            Datum::Multirange { text, kind } => Self::range(*kind, true, text)?,
            Datum::Bit { bits, varying } => Self::bit(*varying, bits)?,
            Datum::Bytea(bytes) => Self::bytea(bytes)?,
            Datum::Inet(n) => Self::Inet(*n),
            Datum::Cidr(n) => Self::Cidr(*n),
            Datum::Macaddr(b) => Self::Macaddr(*b),
            Datum::Macaddr8(b) => Self::Macaddr8(*b),
            Datum::Enum {
                slot,
                member,
                sort,
                label,
            } => Self::Enum {
                slot: *slot,
                member: *member,
                sort: *sort,
                label: SqlName::parse(label)?,
            },
            Datum::Numeric(n) => {
                if n.digits.len() > MAX_DEFAULT_TEXT {
                    return Err(sql_err!(
                        sqlstate::PROGRAM_LIMIT_EXCEEDED,
                        "numeric default too large"
                    ));
                }
                let mut digits = [0u8; MAX_DEFAULT_TEXT];
                digits[..n.digits.len()].copy_from_slice(n.digits);
                Self::Numeric {
                    sign: match n.sign {
                        crate::sql::numeric::Sign::Pos => 0,
                        crate::sql::numeric::Sign::Neg => 1,
                        crate::sql::numeric::Sign::NaN => 2,
                        crate::sql::numeric::Sign::PosInf => 3,
                        crate::sql::numeric::Sign::NegInf => 4,
                    },
                    weight: n.weight,
                    dscale: n.dscale,
                    nbytes: n.digits.len() as u8,
                    digits,
                }
            }
            Datum::Text(s) | Datum::Bpchar(s) => {
                if s.len() > MAX_DEFAULT_TEXT {
                    return Err(sql_err!(
                        sqlstate::PROGRAM_LIMIT_EXCEEDED,
                        "text defaults are limited to {} bytes",
                        MAX_DEFAULT_TEXT
                    ));
                }
                let mut bytes = [0u8; MAX_DEFAULT_TEXT];
                bytes[..s.len()].copy_from_slice(s.as_bytes());
                Self::Text {
                    len: s.len() as u8,
                    bytes,
                }
            }
            Datum::Geometry { kind, text } => {
                let (len, bytes) = Self::bytes(text.as_bytes(), "geometric")?;
                Self::Geometry {
                    kind: *kind,
                    len,
                    bytes,
                }
            }
        })
    }

    pub fn as_datum(&self) -> crate::sql::types::Datum<'_> {
        use crate::sql::types::Datum;
        match self {
            Self::Null => Datum::Null,
            Self::Bool(b) => Datum::Bool(*b),
            Self::Char(byte) => Datum::Char(*byte),
            Self::Int4(v) => Datum::Int4(*v),
            Self::Oid(v) => Datum::Oid(*v),
            Self::Tid(v) => Datum::Tid(*v),
            Self::Cid(v) => Datum::Cid(*v),
            Self::Xid8(v) => Datum::Xid8(*v),
            Self::Snapshot { legacy, len, bytes } => Datum::Snapshot {
                value: crate::sql::snapshot::Snapshot::restore(&bytes[..*len as usize])
                    .expect("stored transaction snapshot was validated"),
                legacy: *legacy,
            },
            Self::PgLsn(v) => Datum::PgLsn(*v),
            Self::AclItem { len, bytes } => Datum::AclItem(
                crate::sql::acl::from_stored(&bytes[..*len as usize])
                    .expect("stored from a valid aclitem"),
            ),
            Self::Money(v) => Datum::Money(*v),
            Self::Int8(v) => Datum::Int8(*v),
            Self::Regtype {
                referenced_oid,
                len,
                bytes,
            } => Datum::Regtype {
                referenced_oid: *referenced_oid,
                name: core::str::from_utf8(&bytes[..*len as usize])
                    .expect("stored from valid UTF-8"),
            },
            Self::RegObject {
                kind,
                referenced_oid,
                len,
                bytes,
            } => Datum::RegObject {
                type_oid: kind.oid(),
                referenced_oid: *referenced_oid,
                name: core::str::from_utf8(&bytes[..*len as usize])
                    .expect("stored from valid UTF-8"),
            },
            Self::Float8(v) => Datum::Float8(*v),
            Self::Date(value) => Datum::Date(*value),
            Self::Timestamp(value) => Datum::Timestamp(*value),
            Self::Timestamptz(value) => Datum::Timestamptz(*value),
            Self::Time(value) => Datum::Time(*value),
            Self::Timetz(time, zone) => Datum::Timetz(*time, *zone),
            Self::Interval(value) => Datum::Interval(*value),
            Self::Uuid(value) => Datum::Uuid(*value),
            Self::Text { len, bytes } => Datum::Text(
                core::str::from_utf8(&bytes[..*len as usize]).expect("stored from valid UTF-8"),
            ),
            Self::PgNodeTree { len, bytes } => Datum::PgNodeTree(
                crate::sql::catalog_node::CatalogNode::from_encoded(
                    core::str::from_utf8(&bytes[..*len as usize]).expect("stored from valid UTF-8"),
                )
                .expect("owned catalog node was validated before storage"),
            ),
            Self::Geometry { kind, len, bytes } => Datum::Geometry {
                kind: *kind,
                text: core::str::from_utf8(&bytes[..*len as usize])
                    .expect("stored from valid UTF-8"),
            },
            Self::TextSearch { query, len, bytes } => {
                let text =
                    core::str::from_utf8(&bytes[..*len as usize]).expect("stored from valid UTF-8");
                if *query {
                    Datum::TsQuery(crate::sql::full_text::restore_query(text))
                } else {
                    Datum::TsVector(crate::sql::full_text::restore_vector(text))
                }
            }
            Self::Numeric {
                sign,
                weight,
                dscale,
                nbytes,
                digits,
            } => Datum::Numeric(crate::sql::numeric::Numeric {
                sign: match sign {
                    0 => crate::sql::numeric::Sign::Pos,
                    1 => crate::sql::numeric::Sign::Neg,
                    2 => crate::sql::numeric::Sign::NaN,
                    3 => crate::sql::numeric::Sign::PosInf,
                    4 => crate::sql::numeric::Sign::NegInf,
                    _ => unreachable!("owned numeric carries a valid sign tag"),
                },
                weight: *weight,
                dscale: *dscale,
                digits: &digits[..*nbytes as usize],
            }),
            Self::Json { jsonb, len, bytes } => Datum::Json {
                text: core::str::from_utf8(&bytes[..*len as usize])
                    .expect("stored from valid UTF-8"),
                jsonb: *jsonb,
            },
            Self::JsonPath { len, bytes } => Datum::JsonPath(
                core::str::from_utf8(&bytes[..*len as usize]).expect("stored from valid UTF-8"),
            ),
            Self::Array {
                element,
                len,
                bytes,
            } => Datum::Array {
                element: element.element(),
                raw: &bytes[..*len as usize],
            },
            Self::Int2Vector {
                lower_bound,
                len,
                bytes,
            } => Datum::Int2Vector {
                lower_bound: *lower_bound,
                raw: &bytes[..*len as usize],
            },
            Self::OidVector {
                lower_bound,
                len,
                bytes,
            } => Datum::OidVector {
                lower_bound: *lower_bound,
                raw: &bytes[..*len as usize],
            },
            Self::Range {
                kind,
                multirange,
                len,
                bytes,
            } => {
                let text =
                    core::str::from_utf8(&bytes[..*len as usize]).expect("stored from valid UTF-8");
                if *multirange {
                    Datum::Multirange { text, kind: *kind }
                } else {
                    Datum::Range { text, kind: *kind }
                }
            }
            Self::Bit {
                varying,
                len,
                bytes,
            } => Datum::Bit {
                bits: core::str::from_utf8(&bytes[..*len as usize])
                    .expect("stored from valid UTF-8"),
                varying: *varying,
            },
            Self::Bytea { len, bytes } => Datum::Bytea(&bytes[..*len as usize]),
            Self::Inet(n) => Datum::Inet(*n),
            Self::Cidr(n) => Datum::Cidr(*n),
            Self::Macaddr(b) => Datum::Macaddr(*b),
            Self::Macaddr8(b) => Datum::Macaddr8(*b),
            Self::Enum {
                slot,
                member,
                sort,
                label,
            } => Datum::Enum {
                slot: *slot,
                member: *member,
                sort: *sort,
                label: label.as_str(),
            },
        }
    }

    fn bytes(value: &[u8], what: &str) -> Result<(u8, [u8; MAX_DEFAULT_TEXT]), SqlError> {
        if value.len() > MAX_DEFAULT_TEXT {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "{} default exceeds the fixed {} byte catalog limit",
                what,
                MAX_DEFAULT_TEXT
            ));
        }
        let mut bytes = [0; MAX_DEFAULT_TEXT];
        bytes[..value.len()].copy_from_slice(value);
        Ok((value.len() as u8, bytes))
    }

    fn json(jsonb: bool, text: &str) -> Result<Self, SqlError> {
        let (len, bytes) = Self::bytes(text.as_bytes(), "JSON")?;
        Ok(Self::Json { jsonb, len, bytes })
    }

    fn array(element: crate::sql::types::ArrElem, raw: &[u8]) -> Result<Self, SqlError> {
        let (len, bytes) = Self::bytes(raw, "array")?;
        Ok(Self::Array {
            element: CachedArrayElement::from_element(element)?,
            len,
            bytes,
        })
    }

    fn range(
        kind: crate::sql::types::RangeKind,
        multirange: bool,
        text: &str,
    ) -> Result<Self, SqlError> {
        let (len, bytes) = Self::bytes(text.as_bytes(), "range")?;
        Ok(Self::Range {
            kind,
            multirange,
            len,
            bytes,
        })
    }

    fn bit(varying: bool, bits: &str) -> Result<Self, SqlError> {
        let (len, bytes) = Self::bytes(bits.as_bytes(), "bit string")?;
        Ok(Self::Bit {
            varying,
            len,
            bytes,
        })
    }

    fn bytea(value: &[u8]) -> Result<Self, SqlError> {
        let (len, bytes) = Self::bytes(value, "bytea")?;
        Ok(Self::Bytea { len, bytes })
    }
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub struct ColumnMeta {
    pub name: SqlName,
    pub ctype: ColType,
    /// PostgreSQL atttypmod: -1 = none. varchar(n)/char(n) encode `n + 4`;
    /// numeric(p,s) encodes `((p<<16)|s) + 4`. Enforced during coercion.
    pub type_mod: i32,
    pub collation: Collation,
    /// PostgreSQL's durable `attstorage` policy. The object-native row format
    /// may choose a different block layout, but catalog and schema identity do
    /// not lose the client-visible setting.
    pub storage: crate::sql::ast::ColumnStorage,
    /// PostgreSQL's durable `attcompression` policy (`Default` is empty in the
    /// catalog). It is retained separately from the object block codec.
    pub compression: crate::sql::ast::ColumnCompression,
    pub not_null: NotNullOrigin,
    /// Whether this column's local NOT NULL constraint participates in
    /// ordinary table inheritance. It is irrelevant for a nullable column.
    pub not_null_inheritable: bool,
    pub unique: bool,
    pub primary: bool,
    /// Implicit identity generation in stored shapes. The SQL builder also
    /// uses this flag before lowering SERIAL to a bound nextval default.
    pub auto_increment: bool,
    /// DEFAULT or `GENERATED ALWAYS AS (...) STORED`, including its source for
    /// catalog rendering and replay.
    pub default: ColumnDefault,
    /// A `GENERATED ... AS IDENTITY` column (also `auto_increment`): distinguishes
    /// it from a bare `serial` for `pg_attribute.attidentity`.
    pub is_identity: bool,
    /// `GENERATED ALWAYS AS IDENTITY` (reject explicit inserts) vs `BY DEFAULT`.
    pub identity_always: bool,
    /// When the column was declared with a user-defined type, its stable
    /// schema-qualified identity. Runtime enum/domain slots are rebound from
    /// this identity after restart.
    pub user_type: Option<UserTypeName>,
    /// PostgreSQL's `attstattarget`; -1 selects the server default.
    pub statistics_target: i16,
    /// PostgreSQL's `attoptions` overrides for the local and inherited
    /// `ANALYZE` paths. This is a typed catalog value, never an option string.
    pub statistics_options: crate::sql::ast::ColumnStatisticsOptions,
    /// PostgreSQL's `attislocal`: the table itself declares the column, as
    /// opposed to receiving it only from an inheritance or partition parent.
    pub local: bool,
}

// Recovery and copied execution schemas reserve at most 512 bytes per column.
const _: () = assert!(core::mem::size_of::<ColumnMeta>() <= 512);

/// Durable provenance of a table column's effective `NOT NULL` constraint.
/// Partitions can retain a local constraint while also inheriting one, so a
/// boolean cannot represent parent ALTER and DETACH semantics.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(u8)]
pub enum NotNullOrigin {
    Nullable = 0,
    Local = 1,
    Inherited = 2,
    LocalAndInherited = 3,
}

impl NotNullOrigin {
    pub const fn local(required: bool) -> Self {
        if required {
            Self::Local
        } else {
            Self::Nullable
        }
    }

    pub const fn from_code(code: u8) -> Option<Self> {
        Some(match code {
            0 => Self::Nullable,
            1 => Self::Local,
            2 => Self::Inherited,
            3 => Self::LocalAndInherited,
            _ => return None,
        })
    }

    pub const fn code(self) -> u8 {
        self as u8
    }

    pub const fn is_required(self) -> bool {
        !matches!(self, Self::Nullable)
    }

    pub const fn is_local(self) -> bool {
        matches!(self, Self::Local | Self::LocalAndInherited)
    }

    pub const fn is_inherited(self) -> bool {
        matches!(self, Self::Inherited | Self::LocalAndInherited)
    }

    pub const fn attach_inherited(self) -> Self {
        Self::Inherited
    }

    pub const fn add_inherited(self) -> Self {
        if self.is_local() {
            Self::LocalAndInherited
        } else {
            Self::Inherited
        }
    }

    pub const fn drop_inherited(self) -> Self {
        if self.is_local() {
            Self::Local
        } else {
            Self::Nullable
        }
    }

    pub const fn add_local(self) -> Self {
        if self.is_inherited() {
            Self::LocalAndInherited
        } else {
            Self::Local
        }
    }

    pub const fn drop_local(self) -> Self {
        if self.is_inherited() {
            Self::Inherited
        } else {
            Self::Nullable
        }
    }

    pub const fn localize(self) -> Self {
        Self::local(self.is_required())
    }
}

/// A type declaration or captured source, with its schema-qualified name.
#[derive(Debug, Clone, Copy)]
pub struct UserTypeName {
    pub schema: SqlName,
    pub name: SqlName,
    binding: type_references::TypeBinding,
}

impl UserTypeName {
    /// A declaration requests name lookup when its type is bound.
    pub const fn declaration(schema: SqlName, name: SqlName) -> Self {
        Self {
            schema,
            name,
            binding: type_references::TypeBinding::Declaration,
        }
    }
}

/// The durable identity of a table column's declared type.
///
/// `ColType` deliberately describes the representation used by the executor;
/// that is not sufficient for a domain, whose values use its base
/// representation while clients must still see the domain OID. Keeping this
/// distinction at one catalog boundary prevents callers from accidentally
/// reporting the storage type.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DeclaredColumnType {
    Builtin {
        oid: i32,
    },
    UserDefined {
        oid: i32,
        schema: SqlName,
        name: SqlName,
    },
}

/// An OID accepted only by prepared-statement parameter inference.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) struct ParameterTypeOid(i32);

impl ParameterTypeOid {
    pub(crate) const fn raw(self) -> i32 {
        self.0
    }
}

impl DeclaredColumnType {
    pub(crate) const fn parameter_oid(self) -> ParameterTypeOid {
        ParameterTypeOid(self.schema_oid())
    }

    pub(crate) const fn catalog_oid(self) -> i32 {
        self.schema_oid()
    }

    pub(crate) const fn replication_oid(self) -> i32 {
        self.schema_oid()
    }

    const fn schema_oid(self) -> i32 {
        match self {
            Self::Builtin { oid } | Self::UserDefined { oid, .. } => oid,
        }
    }

    pub(crate) const fn replication_user_type(self) -> Option<(SqlName, SqlName)> {
        match self {
            Self::Builtin { .. } => None,
            Self::UserDefined { schema, name, .. } => Some((schema, name)),
        }
    }
}

/// Maximum stored length of a non-constant DEFAULT expression's source text.
/// Ample for real defaults (`nextval('schema.seq')`, `now()`,
/// `gen_random_uuid()`, …); a longer one is a loud error, never silent growth.
/// This keeps each copied column definition within the recovery stack envelope.
pub(crate) const DEFAULT_EXPR_MAX: usize = 120;
/// Every accepted view column may carry a default. Keeping the sparse entries
/// at the view-column boundary prevents ALTER VIEW from introducing a narrower
/// catalog-only limit.
// Defaults carry parsed expressions and are substantially larger than column
// names. Keep their fixed resource limit independent from PostgreSQL's
// relation-width boundary so widening rows does not multiply every view slot.
pub(crate) const MAX_VIEW_DEFAULTS: usize = 64;

impl ColumnMeta {
    pub const EMPTY: Self = ColumnMeta {
        name: SqlName::EMPTY,
        ctype: ColType::Bool,
        type_mod: -1,
        collation: Collation::None,
        storage: crate::sql::ast::ColumnStorage::Plain,
        compression: crate::sql::ast::ColumnCompression::Default,
        not_null: NotNullOrigin::Nullable,
        not_null_inheritable: true,
        unique: false,
        primary: false,
        auto_increment: false,
        default: ColumnDefault::NONE,
        is_identity: false,
        identity_always: false,
        user_type: None,
        statistics_target: -1,
        statistics_options: crate::sql::ast::ColumnStatisticsOptions::DEFAULT,
        local: true,
    };
}

/// Per-kind table-constraint capacity. This follows the SQL parser's complete
/// bounded list instead of imposing a smaller storage-only ceiling after DDL
/// has already been accepted.
pub(crate) const MAX_TABLE_CONSTRAINTS: usize = MAX_DEFINITION_ITEMS;
/// Maximum number of named or multi-column UNIQUE/PRIMARY KEY constraints per
/// table. Inline single-column keys use column flags until they need an
/// independent catalog name.
pub(crate) const MAX_UNIQUES: usize = MAX_TABLE_CONSTRAINTS;
/// Maximum number of CHECK constraints per table.
pub(crate) const MAX_CHECKS: usize = MAX_TABLE_CONSTRAINTS;
/// Maximum stored length of a CHECK predicate's source text.
pub(crate) const CHECK_SQL_MAX: usize = 512;
/// Maximum number of FOREIGN KEY constraints per table.
pub(crate) const MAX_FKEYS: usize = MAX_TABLE_CONSTRAINTS;
/// Maximum number of exclusion constraints per table.
pub(crate) const MAX_EXCLUSIONS: usize = MAX_TABLE_CONSTRAINTS;
/// Exclusion predicates share the bounded table-definition footprint with
/// CHECK expressions. Exhaustion is reported while parsing DDL.
pub(crate) const EXCLUSION_PREDICATE_MAX: usize = 128;

/// A referential action for ON DELETE / ON UPDATE. Mirrors the parser's
/// `FkAction` so the storage/WAL/checkpoint layers do not depend on the AST.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum FkAction {
    NoAction,
    Restrict,
    Cascade,
    SetNull,
    SetDefault,
}

impl FkAction {
    pub fn code(self) -> u8 {
        match self {
            FkAction::NoAction => 0,
            FkAction::Restrict => 1,
            FkAction::Cascade => 2,
            FkAction::SetNull => 3,
            FkAction::SetDefault => 4,
        }
    }

    pub fn from_code(c: u8) -> Option<Self> {
        Some(match c {
            0 => FkAction::NoAction,
            1 => FkAction::Restrict,
            2 => FkAction::Cascade,
            3 => FkAction::SetNull,
            4 => FkAction::SetDefault,
            _ => return None,
        })
    }
}

/// Durable constraint check timing. A deferred initial mode can only exist on
/// a deferrable constraint.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ConstraintTiming {
    NotDeferrable,
    DeferrableImmediate,
    DeferrableDeferred,
}

impl ConstraintTiming {
    pub const fn code(self) -> u8 {
        match self {
            Self::NotDeferrable => 0,
            Self::DeferrableImmediate => 1,
            Self::DeferrableDeferred => 2,
        }
    }

    pub const fn from_code(code: u8) -> Option<Self> {
        match code {
            0 => Some(Self::NotDeferrable),
            1 => Some(Self::DeferrableImmediate),
            2 => Some(Self::DeferrableDeferred),
            _ => None,
        }
    }

    pub const fn is_deferrable(self) -> bool {
        !matches!(self, Self::NotDeferrable)
    }

    pub const fn initially_deferred(self) -> bool {
        matches!(self, Self::DeferrableDeferred)
    }
}

/// Durable validation/enforcement state for CHECK and FOREIGN KEY
/// constraints. The enum excludes a validated-but-unenforced state.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ConstraintValidation {
    EnforcedValidated,
    EnforcedNotValid,
    NotEnforced,
}

impl ConstraintValidation {
    pub const fn code(self) -> u8 {
        match self {
            Self::EnforcedValidated => 0,
            Self::EnforcedNotValid => 1,
            Self::NotEnforced => 2,
        }
    }

    pub const fn from_code(code: u8) -> Option<Self> {
        match code {
            0 => Some(Self::EnforcedValidated),
            1 => Some(Self::EnforcedNotValid),
            2 => Some(Self::NotEnforced),
            _ => None,
        }
    }

    pub const fn enforced(self) -> bool {
        !matches!(self, Self::NotEnforced)
    }

    pub const fn validated(self) -> bool {
        matches!(self, Self::EnforcedValidated)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(u8)]
pub enum UniqueKeyKind {
    UniqueNullsDistinct = 0,
    Primary = 1,
    UniqueNullsNotDistinct = 2,
}

impl UniqueKeyKind {
    pub const fn is_primary(self) -> bool {
        matches!(self, Self::Primary)
    }
    pub const fn nulls_not_distinct(self) -> bool {
        matches!(self, Self::UniqueNullsNotDistinct)
    }
    pub const fn code(self) -> u8 {
        self as u8
    }
    pub fn from_code(code: u8) -> Option<Self> {
        match code {
            0 => Some(Self::UniqueNullsDistinct),
            1 => Some(Self::Primary),
            2 => Some(Self::UniqueNullsNotDistinct),
            _ => None,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) struct InlineKeyName {
    pub(crate) attribute: u16,
    pub(crate) name: SqlName,
}

impl InlineKeyName {
    pub(crate) const EMPTY: Self = Self {
        attribute: 0,
        name: SqlName::EMPTY,
    };
}

/// Named, multi-column, deferred or NULLS NOT DISTINCT key constraint.
#[derive(Debug, Clone, Copy)]
pub struct UniqueKey {
    pub(crate) identity: Option<ConstraintIdentity>,
    pub(crate) index_identity: Option<RelationIdentity>,
    pub name: SqlName,
    pub columns: [u16; MAX_INDEX_COLS],
    pub n_cols: usize,
    pub kind: UniqueKeyKind,
    pub timing: ConstraintTiming,
}

impl UniqueKey {
    pub const EMPTY: Self = UniqueKey {
        identity: None,
        index_identity: None,
        name: SqlName::EMPTY,
        columns: [0u16; MAX_INDEX_COLS],
        n_cols: 0,
        kind: UniqueKeyKind::UniqueNullsDistinct,
        timing: ConstraintTiming::NotDeferrable,
    };

    pub fn columns(&self) -> &[u16] {
        &self.columns[..self.n_cols]
    }
}

/// The commutative binary operator, by `pg_operator` OID, that an exclusion
/// constraint compares one element with: a built-in the evaluator runs
/// directly, or a user-defined operator run through its function.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ExclusionOperator {
    oid: i32,
    binary: Option<crate::sql::ast::BinaryOp>,
}

impl ExclusionOperator {
    /// `None` unless `oid` is a built-in binary operator the evaluator runs.
    pub(crate) fn from_oid(oid: i32) -> Option<Self> {
        let (name, ..) = crate::sql::catalog::builtin_binary_operator_row(oid)?;
        Some(Self {
            oid,
            binary: Some(crate::sql::ast::BinaryOp::from_operator_name(name)?),
        })
    }

    /// A user-defined operator, by its catalog OID.
    pub(crate) fn user(oid: i32) -> Option<Self> {
        (oid >= OPERATOR_OID_BASE).then_some(Self { oid, binary: None })
    }

    /// A stored operator OID: a runnable built-in or a user-defined operator.
    pub(crate) fn from_stored(oid: i32) -> Option<Self> {
        Self::from_oid(oid).or_else(|| Self::user(oid))
    }

    pub(crate) const fn oid(self) -> i32 {
        self.oid
    }

    /// The built-in operator's evaluator form; `None` for a user operator.
    pub(crate) const fn binary(self) -> Option<crate::sql::ast::BinaryOp> {
        self.binary
    }

    /// The built-in operator's name; `None` for a user operator, which the
    /// catalog names.
    pub(crate) fn builtin_sql(self) -> Option<&'static str> {
        crate::sql::catalog::builtin_binary_operator_row(self.oid).map(|row| row.0)
    }

    /// Range equality, the operator of `EMPTY`'s unused positions.
    const RANGE_EQUAL: Self = Self {
        oid: 3882,
        binary: Some(crate::sql::ast::BinaryOp::Eq),
    };
}

/// How one exclusion element is indexed: the operator class as written
/// (`None` when omitted, so the definition prints back as written) and the
/// class it resolved to, the key's collation (`explicit_collation` when a
/// written one differs from the key's own) and the btree ordering options.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) struct ExclusionKeyOptions {
    pub(crate) class: Option<IndexOperatorClass>,
    pub(crate) resolved_class: Option<IndexOperatorClass>,
    pub(crate) collation: crate::sql::ast::Collation,
    pub(crate) explicit_collation: bool,
    pub(crate) descending: bool,
    pub(crate) nulls_first: bool,
}

impl ExclusionKeyOptions {
    pub(crate) const DEFAULT: Self = Self {
        class: None,
        resolved_class: None,
        collation: crate::sql::ast::Collation::None,
        explicit_collation: false,
        descending: false,
        nulls_first: false,
    };
}

/// One element an exclusion constraint compares: a table column, or a
/// canonical expression over the table's columns (PostgreSQL's `indkey` 0).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ExclusionElement<'a> {
    Column(u16),
    Expression(&'a str),
}

/// Where one element's key lives inside its constraint.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ExclusionKey {
    Column(u16),
    /// A span of `ExclusionConstraint::expression_text`.
    Expression {
        start: u16,
        len: u16,
    },
}

/// Exclusion constraints keep their elements beside each other in one
/// bounded text so a table definition stays fixed-size; the elements' total
/// canonical expression text cannot exceed this many bytes.
pub(crate) const EXCLUSION_EXPRESSIONS_MAX: usize = 256;

#[derive(Debug, Clone, Copy)]
pub struct ExclusionConstraint {
    pub(crate) identity: Option<ConstraintIdentity>,
    pub(crate) index_identity: Option<RelationIdentity>,
    pub name: SqlName,
    /// The index access method that enforces the constraint.
    pub method: crate::sql::ast::IndexAccessMethod,
    /// Elements are written only through `push`, so a key never names text
    /// outside `expression_text`.
    keys: [ExclusionKey; MAX_INDEX_COLS],
    operators: [ExclusionOperator; MAX_INDEX_COLS],
    options: [ExclusionKeyOptions; MAX_INDEX_COLS],
    n_cols: usize,
    expression_text: StackStr<EXCLUSION_EXPRESSIONS_MAX>,
    pub predicate: Option<StackStr<EXCLUSION_PREDICATE_MAX>>,
    pub timing: ConstraintTiming,
}

impl ExclusionConstraint {
    pub const EMPTY: Self = Self {
        identity: None,
        index_identity: None,
        name: SqlName::EMPTY,
        method: crate::sql::ast::IndexAccessMethod::Gist,
        keys: [ExclusionKey::Column(0); MAX_INDEX_COLS],
        operators: [ExclusionOperator::RANGE_EQUAL; MAX_INDEX_COLS],
        options: [ExclusionKeyOptions::DEFAULT; MAX_INDEX_COLS],
        n_cols: 0,
        expression_text: StackStr::new(),
        predicate: None,
        timing: ConstraintTiming::NotDeferrable,
    };

    pub const fn len(&self) -> usize {
        self.n_cols
    }

    pub const fn is_empty(&self) -> bool {
        self.n_cols == 0
    }

    pub fn element(&self, position: usize) -> ExclusionElement<'_> {
        match self.keys[..self.n_cols][position] {
            ExclusionKey::Column(column) => ExclusionElement::Column(column),
            ExclusionKey::Expression { start, len } => ExclusionElement::Expression(
                &self.expression_text.as_str()
                    [usize::from(start)..usize::from(start) + usize::from(len)],
            ),
        }
    }

    pub fn elements(&self) -> impl Iterator<Item = ExclusionElement<'_>> + Clone + '_ {
        (0..self.n_cols).map(|position| self.element(position))
    }

    pub fn operators(&self) -> &[ExclusionOperator] {
        &self.operators[..self.n_cols]
    }

    /// Each element's operator class and collation as written.
    pub(crate) fn options(&self) -> &[ExclusionKeyOptions] {
        &self.options[..self.n_cols]
    }

    /// The table columns that are elements themselves (`conkey` entries
    /// other than 0).
    pub fn element_columns(&self) -> impl Iterator<Item = u16> + Clone + '_ {
        self.elements().filter_map(|element| match element {
            ExclusionElement::Column(column) => Some(column),
            ExclusionElement::Expression(_) => None,
        })
    }

    /// Whether both constraints compare the same elements with the same
    /// operators, operator classes and collations.
    pub fn same_elements(&self, other: &Self) -> bool {
        self.operators() == other.operators()
            && self.options() == other.options()
            && self.elements().eq(other.elements())
    }

    /// Appends one element. Exhaustion of the element or expression-text
    /// reservation is `54000`.
    pub(crate) fn push(
        &mut self,
        element: ExclusionElement<'_>,
        operator: ExclusionOperator,
        options: ExclusionKeyOptions,
    ) -> Result<(), SqlError> {
        if self.n_cols == MAX_INDEX_COLS {
            return Err(sql_err!(
                sqlstate::TOO_MANY_COLUMNS,
                "cannot use more than {} columns in an index",
                MAX_INDEX_COLS
            ));
        }
        self.keys[self.n_cols] = match element {
            ExclusionElement::Column(column) => ExclusionKey::Column(column),
            ExclusionElement::Expression(text) => {
                let start = self.expression_text.len();
                if text.is_empty() || start + text.len() > EXCLUSION_EXPRESSIONS_MAX {
                    return Err(sql_err!(
                        sqlstate::PROGRAM_LIMIT_EXCEEDED,
                        "exclusion constraint expressions exceed {} bytes",
                        EXCLUSION_EXPRESSIONS_MAX
                    ));
                }
                let _ = core::fmt::Write::write_str(&mut self.expression_text, text);
                ExclusionKey::Expression {
                    start: start as u16,
                    len: text.len() as u16,
                }
            }
        };
        self.operators[self.n_cols] = operator;
        self.options[self.n_cols] = options;
        self.n_cols += 1;
        Ok(())
    }

    /// This constraint with no elements yet, for rebuilding them.
    pub(crate) fn without_elements(&self) -> Self {
        let mut cleared = *self;
        cleared.n_cols = 0;
        cleared.expression_text = StackStr::new();
        cleared
    }

    /// Renumbers each column element through `map`; expressions, which
    /// name their columns, are kept.
    pub(crate) fn map_columns(
        &self,
        mut map: impl FnMut(u16) -> Result<u16, SqlError>,
    ) -> Result<Self, SqlError> {
        let mut mapped = *self;
        for key in &mut mapped.keys[..self.n_cols] {
            if let ExclusionKey::Column(column) = key {
                *column = map(*column)?;
            }
        }
        Ok(mapped)
    }

    /// Rebuilds the elements through `map`, which sees each element and
    /// returns its replacement; the operators are kept.
    pub(crate) fn map_elements<'t>(
        &self,
        mut map: impl FnMut(ExclusionElement<'_>) -> Result<ExclusionElement<'t>, SqlError>,
    ) -> Result<Self, SqlError> {
        let mut mapped = self.without_elements();
        for position in 0..self.n_cols {
            mapped.push(
                map(self.element(position))?,
                self.operators[position],
                self.options[position],
            )?;
        }
        Ok(mapped)
    }
}

/// A CHECK constraint: its source predicate text, re-parsed and evaluated per
/// candidate row at INSERT/UPDATE time.
#[derive(Debug, Clone, Copy)]
pub struct CheckConstraint {
    pub(crate) identity: Option<ConstraintIdentity>,
    pub name: SqlName,
    pub expression: StackStr<CHECK_SQL_MAX>,
    pub validation: ConstraintValidation,
    /// `NO INHERIT`: the table's children neither receive nor need it.
    pub no_inherit: bool,
}

impl CheckConstraint {
    pub const EMPTY: Self = CheckConstraint {
        identity: None,
        name: SqlName::EMPTY,
        expression: StackStr::new(),
        validation: ConstraintValidation::EnforcedValidated,
        no_inherit: false,
    };
}

/// The unique index of the referenced table a foreign key depends on
/// (PostgreSQL's `conindid`), chosen when the key is created.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum ReferencedIndex {
    /// The table's own primary key, created by the same statement: chosen
    /// once the statement's new keys have their identities.
    PendingPrimaryKey,
    /// The oldest immediate unique key over the referenced columns among
    /// those the same statement creates on the table, chosen likewise.
    PendingKey,
    /// The index's relation identity.
    Index(RelationIdentity),
}

impl ReferencedIndex {
    pub(crate) const fn identity(self) -> Option<RelationIdentity> {
        match self {
            Self::Index(identity) => Some(identity),
            Self::PendingPrimaryKey | Self::PendingKey => None,
        }
    }
}

/// A FOREIGN KEY constraint on a child table's column tuple referencing a
/// parent table's column tuple.
#[derive(Debug, Clone, Copy)]
pub struct ForeignKey {
    pub(crate) identity: Option<ConstraintIdentity>,
    pub(crate) referenced_index: ReferencedIndex,
    pub name: SqlName,
    pub columns: [u16; MAX_INDEX_COLS],
    pub n_cols: usize,
    pub parent_schema: SqlName,
    pub parent: SqlName,
    pub parent_cols: [u16; MAX_INDEX_COLS],
    pub n_parent_cols: usize,
    pub on_delete: FkAction,
    /// The referencing columns `ON DELETE SET NULL (...)` or `SET DEFAULT
    /// (...)` changes, in written order (PostgreSQL's `confdelsetcols`);
    /// none means every key column.
    pub delete_set_cols: [u16; MAX_INDEX_COLS],
    pub n_delete_set_cols: usize,
    pub on_update: FkAction,
    pub timing: ConstraintTiming,
    pub validation: ConstraintValidation,
    /// The firing modes of the foreign key's four RI triggers, indexed by
    /// [`ForeignKeyTrigger::ordinal`] (PostgreSQL's `tgenabled`): `ALTER
    /// TABLE ... ENABLE/DISABLE TRIGGER` on the referencing or referenced
    /// table changes them.
    pub(crate) trigger_enabled: [TriggerEnabled; 4],
}

impl ForeignKey {
    pub const EMPTY: Self = ForeignKey {
        identity: None,
        referenced_index: ReferencedIndex::PendingKey,
        name: SqlName::EMPTY,
        parent_schema: SqlName::EMPTY,
        columns: [0u16; MAX_INDEX_COLS],
        n_cols: 0,
        parent: SqlName::EMPTY,
        parent_cols: [0u16; MAX_INDEX_COLS],
        n_parent_cols: 0,
        on_delete: FkAction::NoAction,
        delete_set_cols: [0u16; MAX_INDEX_COLS],
        n_delete_set_cols: 0,
        on_update: FkAction::NoAction,
        timing: ConstraintTiming::NotDeferrable,
        validation: ConstraintValidation::EnforcedValidated,
        trigger_enabled: [TriggerEnabled::Origin; 4],
    };

    pub(crate) const fn trigger_enabled(&self, trigger: ForeignKeyTrigger) -> TriggerEnabled {
        self.trigger_enabled[trigger.ordinal()]
    }

    pub fn columns(&self) -> &[u16] {
        &self.columns[..self.n_cols]
    }

    pub fn delete_set_cols(&self) -> &[u16] {
        &self.delete_set_cols[..self.n_delete_set_cols]
    }

    pub fn parent_cols(&self) -> &[u16] {
        &self.parent_cols[..self.n_parent_cols]
    }
}

pub trait DefinitionBacking: Clone + core::fmt::Debug {
    type Inputs: AsRef<StoredTypeInputs> + Clone + core::fmt::Debug;
    type Slice<T: Copy + core::fmt::Debug + 'static, const N: usize>: AsRef<[T]>
        + Clone
        + core::fmt::Debug;
}

#[derive(Debug, Clone, Copy)]
pub struct InlineDefinition;

impl DefinitionBacking for InlineDefinition {
    type Inputs = StoredTypeInputs;
    type Slice<T: Copy + core::fmt::Debug + 'static, const N: usize> = [T; N];
}

#[derive(Debug, Clone, Copy)]
pub struct StoredDefinition;

impl DefinitionBacking for StoredDefinition {
    type Inputs = StoredTypeInputs;
    type Slice<T: Copy + core::fmt::Debug + 'static, const N: usize> =
        crate::mem::lease_pool::SharedSlice<T>;
}

#[derive(Debug, Clone, Copy)]
pub struct BorrowedDefinition<'a>(core::marker::PhantomData<&'a ()>);

impl<'a> DefinitionBacking for BorrowedDefinition<'a> {
    type Inputs = &'a StoredTypeInputs;
    type Slice<T: Copy + core::fmt::Debug + 'static, const N: usize> = &'a [T];
}

pub(crate) type TableDef = TableDefinition<StoredDefinition>;
pub(crate) type TableDefBuilder = TableDefinition<InlineDefinition>;
pub(crate) type TableDefView<'a> = TableDefinition<BorrowedDefinition<'a>>;

#[derive(Debug, Clone)]
pub struct TableDefinition<B: DefinitionBacking> {
    pub(crate) type_inputs: B::Inputs,
    /// The schema the table lives in ("public" unless created qualified or
    /// under a search_path naming another schema).
    pub schema: SqlName,
    pub name: SqlName,
    pub kind: TableKind,
    pub persistence: RelationPersistence,
    pub on_commit: OnCommitAction,
    /// The durable PostgreSQL-visible table access method. The object-native
    /// row representation implements the ordinary heap relation contract.
    pub access_method: TableAccessMethod,
    /// PostgreSQL heap options with an executable object-native effect.
    pub storage_options: TableStorageOptions,
    /// Stable tablespace identity; zero is the database default.
    pub tablespace: u16,
    pub columns: B::Slice<ColumnMeta, MAX_COLUMNS>,
    pub n_columns: usize,
    pub(crate) not_null_names: B::Slice<Option<SqlName>, MAX_COLUMNS>,
    pub(crate) not_null_name_edits: ColumnSet,
    pub(crate) attribute_identities: B::Slice<AttributeIdentities, MAX_RELATION_COLUMNS>,
    pub(crate) attributes: column_attributes::ColumnAttributes<B>,
    pub(crate) inline_index_identities: B::Slice<Option<RelationIdentity>, MAX_RELATION_COLUMNS>,
    pub(crate) inline_constraint_identities:
        B::Slice<Option<ConstraintIdentity>, MAX_RELATION_COLUMNS>,
    pub(crate) inline_key_names: B::Slice<InlineKeyName, MAX_COLUMNS>,
    pub(crate) n_inline_key_names: usize,
    pub uniques: B::Slice<UniqueKey, MAX_UNIQUES>,
    pub n_uniques: usize,
    pub checks: B::Slice<CheckConstraint, MAX_CHECKS>,
    pub n_checks: usize,
    pub fkeys: B::Slice<ForeignKey, MAX_FKEYS>,
    pub n_fkeys: usize,
    pub exclusions: B::Slice<ExclusionConstraint, MAX_EXCLUSIONS>,
    pub n_exclusions: usize,
    /// What the CHECK constraints and column expressions were bound to.
    pub(crate) expression_dependencies:
        B::Slice<ExpressionDependency, MAX_TABLE_EXPRESSION_DEPENDENCIES>,
    pub(crate) n_expression_dependencies: usize,
    /// PostgreSQL retains a table's TOAST relation after the last toastable
    /// column is dropped. This catalog bit records that irreversible creation.
    pub has_toast: bool,
    pub(crate) toast_index_identity: Option<RelationIdentity>,
    /// PostgreSQL leaves `relhasrules` set after the last rule is dropped.
    pub has_rules: bool,
    pub row_level_security: RowLevelSecurityState,
    /// The table-owned replica-identity mode. `Index` normally has one
    /// selected index definition, but PostgreSQL retains this mode when a
    /// dependent index disappears with a dropped column.
    pub replica_identity: ReplicaIdentityMode,
    /// The primary key or unique constraint index, by its identity, that
    /// `CLUSTER ON` and `REPLICA IDENTITY USING INDEX` selected. Other
    /// indexes carry these marks on their own definitions.
    pub(crate) key_index_marks: KeyIndexMarks,
    /// Direct PostgreSQL table-inheritance parents. Slots are durable catalog
    /// identities; a parent cannot be dropped or reused while this edge exists.
    pub inheritance: TableInheritance,
    /// A typed table retains the composite type identity it was declared `OF`.
    /// The table's own row type remains distinct, as PostgreSQL requires.
    pub type_membership: TableTypeMembership,
    pub partition: PartitionDef,
}

impl Copy for TableDefinition<BorrowedDefinition<'_>> {}

/// The key indexes a table's `CLUSTER ON` and `REPLICA IDENTITY USING INDEX`
/// select, by index identity. A key index has no index slot of its own to
/// carry `pg_index.indisclustered` and `indisreplident`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) struct KeyIndexMarks {
    pub clustered: Option<RelationIdentity>,
    pub replica_identity: Option<RelationIdentity>,
}

impl KeyIndexMarks {
    pub(crate) const NONE: Self = Self {
        clustered: None,
        replica_identity: None,
    };

    /// Each mark as its creation stamp, zero when unset.
    pub(crate) fn encode(self) -> [u64; 2] {
        [self.clustered, self.replica_identity]
            .map(|mark| mark.map_or(0, RelationIdentity::created_at))
    }

    pub(crate) fn decode(stamps: [u64; 2]) -> Option<Self> {
        let mark = |stamp: u64| match stamp {
            0 => Some(None),
            stamp => RelationIdentity::parse(stamp).map(Some),
        };
        Some(Self {
            clustered: mark(stamps[0])?,
            replica_identity: mark(stamps[1])?,
        })
    }
}

impl<B: DefinitionBacking> TableDefinition<B> {
    /// The key index identities of the table's primary key and unique
    /// constraints.
    pub(crate) fn key_index_identities(&self) -> impl Iterator<Item = RelationIdentity> + '_ {
        (0..usize::from(self.attributes.count))
            .filter(
                |&attribute| match self.attributes.slots.as_ref()[attribute] {
                    column_attributes::AttributeSlot::Live(column) => {
                        let column = &self.columns.as_ref()[usize::from(column)];
                        column.primary || column.unique
                    }
                    _ => false,
                },
            )
            .filter_map(|attribute| self.inline_index_identities.as_ref()[attribute])
            .chain(self.uniques().iter().filter_map(|key| key.index_identity))
    }

    /// The columns of the key whose index is `identity`.
    pub(crate) fn key_index_columns(&self, identity: RelationIdentity) -> Option<ColumnSet> {
        let mut columns = ColumnSet::EMPTY;
        if let Some(column) = (0..self.n_columns).find(|&column| {
            let metadata = &self.columns.as_ref()[column];
            (metadata.primary || metadata.unique)
                && self.column_index_identity(column) == Some(identity)
        }) {
            columns.insert(column);
            return Some(columns);
        }
        let key = self
            .uniques()
            .iter()
            .find(|key| key.index_identity == Some(identity))?;
        for &column in key.columns() {
            columns.insert(usize::from(column));
        }
        Some(columns)
    }

    /// Whether every mark names one of the table's key indexes.
    pub(crate) fn key_index_marks_valid(&self) -> bool {
        [
            self.key_index_marks.clustered,
            self.key_index_marks.replica_identity,
        ]
        .into_iter()
        .flatten()
        .all(|mark| self.key_index_identities().any(|identity| identity == mark))
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct TableStorageOptions {
    pub fillfactor: Option<u8>,
}

impl TableStorageOptions {
    pub const DEFAULT: Self = Self { fillfactor: None };
}

/// Typed-table membership retains the composite source's complete lifetime.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TableTypeMembership {
    None,
    Composite(TypeReference),
}

impl TableTypeMembership {
    pub const NONE: Self = Self::None;

    pub fn composite_slot(self) -> Option<usize> {
        match self {
            Self::None => None,
            Self::Composite(reference) => reference.composite_slot(),
        }
    }
}

/// The durable table modes of PostgreSQL logical replica identity. The index
/// choice itself lives on the selected index so index lifecycle, WAL and
/// catalog rendering share one owner. `Index` may deliberately have no
/// selection after PostgreSQL drops a dependent index.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ReplicaIdentityMode {
    Default,
    Full,
    Nothing,
    Index,
}

impl ReplicaIdentityMode {
    pub const DEFAULT: Self = Self::Default;

    pub const fn code(self) -> u8 {
        match self {
            Self::Default => b'd',
            Self::Full => b'f',
            Self::Nothing => b'n',
            Self::Index => b'i',
        }
    }

    pub const fn from_code(code: u8) -> Option<Self> {
        match code {
            b'd' => Some(Self::Default),
            b'f' => Some(Self::Full),
            b'n' => Some(Self::Nothing),
            b'i' => Some(Self::Index),
            _ => None,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TableKind {
    Local,
    Foreign,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RelationPersistence {
    Permanent,
    Unlogged,
    Temporary,
}

impl RelationPersistence {
    pub const fn code(self) -> u8 {
        match self {
            Self::Permanent => b'p',
            Self::Unlogged => b'u',
            Self::Temporary => b't',
        }
    }

    pub const fn from_code(code: u8) -> Option<Self> {
        match code {
            b'p' => Some(Self::Permanent),
            b'u' => Some(Self::Unlogged),
            b't' => Some(Self::Temporary),
            _ => None,
        }
    }
}

impl From<crate::sql::ast::RelationPersistence> for RelationPersistence {
    fn from(value: crate::sql::ast::RelationPersistence) -> Self {
        match value {
            crate::sql::ast::RelationPersistence::Permanent => Self::Permanent,
            crate::sql::ast::RelationPersistence::Unlogged => Self::Unlogged,
            crate::sql::ast::RelationPersistence::Temporary => Self::Temporary,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum OnCommitAction {
    PreserveRows,
    DeleteRows,
    Drop,
}

impl From<crate::sql::ast::OnCommitAction> for OnCommitAction {
    fn from(value: crate::sql::ast::OnCommitAction) -> Self {
        match value {
            crate::sql::ast::OnCommitAction::PreserveRows => Self::PreserveRows,
            crate::sql::ast::OnCommitAction::DeleteRows => Self::DeleteRows,
            crate::sql::ast::OnCommitAction::Drop => Self::Drop,
        }
    }
}

/// The table access methods that have an executable object-native relation
/// implementation. A closed type prevents an accepted catalog spelling from
/// becoming behaviorless metadata.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TableAccessMethod {
    /// A partitioned table created without `USING` or reset to `DEFAULT`:
    /// `pg_class.relam` is zero, and each new partition takes
    /// `default_table_access_method`.
    Unspecified,
    Heap,
    /// A database-local table access method. The OID, not its mutable name or
    /// storage slot, crosses table definitions, WAL, and checkpoints.
    Catalog(AccessMethodOid),
}

impl TableAccessMethod {
    pub const fn builtin_code(self) -> Option<u8> {
        match self {
            Self::Heap => Some(0),
            Self::Unspecified | Self::Catalog(_) => None,
        }
    }

    /// `pg_class.relam`.
    pub fn relam(self) -> i32 {
        match self {
            Self::Unspecified => 0,
            Self::Heap => 2,
            Self::Catalog(oid) => oid.get(),
        }
    }
}

/// The two independent pg_class row-security flags. A policy may exist while
/// enforcement is disabled, and FORCE affects only the ordinary owner bypass.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct RowLevelSecurityState {
    pub enabled: bool,
    pub forced: bool,
}

impl RowLevelSecurityState {
    pub const DISABLED: Self = Self {
        enabled: false,
        forced: false,
    };
}

/// A table's independent partitioning and attachment roles. Parent links are
/// storage slots, so renames cannot stale routing metadata. Keeping the roles
/// orthogonal permits a partition to be partitioned without an ambiguous enum
/// state.
#[derive(Debug, Clone, Copy)]
pub struct PartitionDef {
    pub scheme: Option<PartitionScheme>,
    pub attachment: Option<PartitionAttachment>,
    /// A concurrent detach leaves this typed bound on the child.  It is the
    /// executable equivalent of PostgreSQL's generated partition CHECK.
    pub detached_bound: Option<DetachedPartitionBound>,
}

/// The parent partitioning rule retained by a concurrently detached child.
/// Keeping the resolved key positions and bound together avoids re-parsing a
/// catalog expression on every row write.
#[derive(Debug, Clone, Copy)]
pub struct DetachedPartitionBound {
    pub(crate) identity: Option<ConstraintIdentity>,
    /// PostgreSQL-visible generated CHECK identity. It is absent for HASH,
    /// whose concurrent detach does not create a constraint.
    pub name: SqlName,
    pub scheme: PartitionScheme,
    pub bound: PartitionBound,
}

/// Direct ordinary-inheritance parents follow the parser's bounded list.
pub(crate) const MAX_TABLE_INHERITANCE_PARENTS: usize = MAX_DEFINITION_ITEMS;

/// Direct table-inheritance edges.  This is deliberately separate from
/// partition attachment: a partition owns routing and cannot also be treated
/// as an ordinary inherited child merely because both affect relation scans.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct TableInheritance {
    parents: [u16; MAX_TABLE_INHERITANCE_PARENTS],
    n_parents: u8,
}

impl TableInheritance {
    pub const NONE: Self = Self {
        parents: [0; MAX_TABLE_INHERITANCE_PARENTS],
        n_parents: 0,
    };

    pub fn parents_ref(&self) -> &[u16] {
        &self.parents[..usize::from(self.n_parents)]
    }

    pub fn contains(&self, parent: usize) -> bool {
        u16::try_from(parent)
            .ok()
            .is_some_and(|parent| self.parents_ref().contains(&parent))
    }

    pub fn append(&mut self, parent: usize) -> Result<(), SqlError> {
        let parent = u16::try_from(parent).map_err(|_| {
            sql_err!(
                crate::sql::eval::sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "too many tables"
            )
        })?;
        if self.parents_ref().contains(&parent) {
            return Err(sql_err!(
                crate::sql::eval::sqlstate::DUPLICATE_TABLE,
                "relation already inherits from the specified parent"
            ));
        }
        let index = usize::from(self.n_parents);
        if index == self.parents.len() {
            return Err(sql_err!(
                crate::sql::eval::sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "a table can inherit from at most {} parents",
                MAX_TABLE_INHERITANCE_PARENTS
            ));
        }
        self.parents[index] = parent;
        self.n_parents += 1;
        Ok(())
    }

    pub fn remove(&mut self, parent: usize) -> bool {
        let Some(parent) = u16::try_from(parent).ok() else {
            return false;
        };
        let Some(index) = self
            .parents_ref()
            .iter()
            .position(|stored| *stored == parent)
        else {
            return false;
        };
        let count = usize::from(self.n_parents);
        self.parents.copy_within(index + 1..count, index);
        self.n_parents -= 1;
        self.parents[count - 1] = 0;
        true
    }
}

#[derive(Debug, Clone, Copy)]
pub struct PartitionScheme {
    pub strategy: PartitionStrategy,
    pub keys: [u16; MAX_PARTITION_KEYS],
    pub n_keys: u8,
}

#[derive(Debug, Clone, Copy)]
pub struct PartitionAttachment {
    pub parent: u16,
    pub bound: PartitionBound,
    pub state: PartitionAttachmentState,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PartitionAttachmentState {
    Attached,
    DetachPending,
}

impl PartitionAttachmentState {
    pub const fn routable(self) -> bool {
        matches!(self, Self::Attached)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PartitionStrategy {
    Range,
    List,
    Hash,
}

#[derive(Debug, Clone, Copy)]
pub enum PartitionBoundValue {
    MinValue,
    Value(OwnedDatum),
    MaxValue,
}

#[derive(Debug, Clone, Copy)]
pub enum PartitionBound {
    Default,
    Range {
        lower: [PartitionBoundValue; MAX_PARTITION_KEYS],
        upper: [PartitionBoundValue; MAX_PARTITION_KEYS],
        n_keys: u8,
    },
    /// List bounds have one key; tuple-list grammar is rejected at DDL time
    /// rather than stored ambiguously.
    List {
        values: [OwnedDatum; MAX_PARTITION_LIST_VALUES],
        n_values: u8,
    },
    Hash {
        modulus: u32,
        remainder: u32,
    },
}

impl PartitionDef {
    pub const NONE: Self = Self {
        scheme: None,
        attachment: None,
        detached_bound: None,
    };

    pub const fn parent(
        strategy: PartitionStrategy,
        keys: [u16; MAX_PARTITION_KEYS],
        n_keys: u8,
    ) -> Self {
        Self {
            scheme: Some(PartitionScheme {
                strategy,
                keys,
                n_keys,
            }),
            attachment: None,
            detached_bound: None,
        }
    }

    pub const fn child(parent: u16, bound: PartitionBound) -> Self {
        Self {
            scheme: None,
            attachment: Some(PartitionAttachment {
                parent,
                bound,
                state: PartitionAttachmentState::Attached,
            }),
            detached_bound: None,
        }
    }

    pub const fn is_partitioned(self) -> bool {
        self.scheme.is_some()
    }

    pub const fn is_attached(self) -> bool {
        self.attachment.is_some()
    }
}

/// PostgreSQL 18 source boundary (`PARTITION_MAX_KEYS`):
/// https://github.com/postgres/postgres/blob/REL_18_STABLE/src/include/pg_config_manual.h
pub(crate) const MAX_PARTITION_KEYS: usize = 32;
/// LIST bounds follow the parser's complete bounded value list instead of
/// imposing a narrower storage-only limit.
pub(crate) const MAX_PARTITION_LIST_VALUES: usize = MAX_DEFINITION_ITEMS;

impl<B: DefinitionBacking> TableDefinition<B> {
    pub(crate) fn borrowed(&self) -> TableDefView<'_> {
        TableDefinition {
            type_inputs: self.type_inputs.as_ref(),
            schema: self.schema,
            name: self.name,
            kind: self.kind,
            persistence: self.persistence,
            on_commit: self.on_commit,
            access_method: self.access_method,
            storage_options: self.storage_options,
            tablespace: self.tablespace,
            n_columns: self.n_columns,
            not_null_name_edits: self.not_null_name_edits,
            n_inline_key_names: self.n_inline_key_names,
            n_uniques: self.n_uniques,
            n_checks: self.n_checks,
            n_fkeys: self.n_fkeys,
            n_exclusions: self.n_exclusions,
            n_expression_dependencies: self.n_expression_dependencies,
            has_toast: self.has_toast,
            toast_index_identity: self.toast_index_identity,
            has_rules: self.has_rules,
            row_level_security: self.row_level_security,
            replica_identity: self.replica_identity,
            key_index_marks: self.key_index_marks,
            inheritance: self.inheritance,
            type_membership: self.type_membership,
            partition: self.partition,
            columns: &self.columns.as_ref()[..self.n_columns],
            not_null_names: &self.not_null_names.as_ref()[..self.n_columns],
            attribute_identities: &self.attribute_identities.as_ref()
                [..usize::from(self.attributes.count)],
            inline_index_identities: &self.inline_index_identities.as_ref()
                [..usize::from(self.attributes.count)],
            inline_constraint_identities: &self.inline_constraint_identities.as_ref()
                [..usize::from(self.attributes.count)],
            inline_key_names: &self.inline_key_names.as_ref()[..self.n_inline_key_names],
            uniques: &self.uniques.as_ref()[..self.n_uniques],
            checks: &self.checks.as_ref()[..self.n_checks],
            fkeys: &self.fkeys.as_ref()[..self.n_fkeys],
            exclusions: &self.exclusions.as_ref()[..self.n_exclusions],
            expression_dependencies: &self.expression_dependencies.as_ref()
                [..self.n_expression_dependencies],
            attributes: column_attributes::ColumnAttributes {
                count: self.attributes.count,
                slots: &self.attributes.slots.as_ref()[..usize::from(self.attributes.count)],
            },
        }
    }

    pub(crate) fn attribute_number(&self, column: usize) -> u16 {
        self.attributes
            .number(column)
            .expect("admitted table column has a stable attribute number")
    }

    pub(crate) fn attribute_column(&self, number: u16) -> Option<usize> {
        self.attributes.column(number)
    }

    pub fn columns(&self) -> &[ColumnMeta] {
        &self.columns.as_ref()[..self.n_columns]
    }

    pub(crate) fn inline_key_names(&self) -> &[InlineKeyName] {
        &self.inline_key_names.as_ref()[..self.n_inline_key_names]
    }

    pub(crate) fn column_key_name(&self, column: usize) -> Option<SqlName> {
        let attribute = self.attributes.number(column)?;
        self.inline_key_names()
            .iter()
            .find(|key| key.attribute == attribute)
            .map(|key| key.name)
    }

    pub(crate) fn backing_index_names(
        &self,
    ) -> impl Iterator<Item = (SqlName, Option<RelationIdentity>)> + '_ {
        self.columns()
            .iter()
            .enumerate()
            .filter(|(_, column)| column.primary || column.unique)
            .filter_map(|(column, _)| {
                self.column_key_name(column)
                    .map(|name| (name, self.column_index_identity(column)))
            })
            .chain(
                self.uniques()
                    .iter()
                    .map(|key| (key.name, key.index_identity)),
            )
            .chain(
                self.exclusions()
                    .iter()
                    .map(|key| (key.name, key.index_identity)),
            )
    }

    pub fn uniques(&self) -> &[UniqueKey] {
        &self.uniques.as_ref()[..self.n_uniques]
    }

    pub fn checks(&self) -> &[CheckConstraint] {
        &self.checks.as_ref()[..self.n_checks]
    }

    pub fn fkeys(&self) -> &[ForeignKey] {
        &self.fkeys.as_ref()[..self.n_fkeys]
    }

    pub fn exclusions(&self) -> &[ExclusionConstraint] {
        &self.exclusions.as_ref()[..self.n_exclusions]
    }

    pub fn column_index(&self, name: &str) -> Option<usize> {
        self.columns().iter().position(|c| c.name.as_str() == name)
    }

    /// Column types into a caller-provided array, for the row codec.
    pub fn schema(&self, out: &mut [ColType; MAX_COLUMNS]) -> usize {
        for (i, c) in self.columns().iter().enumerate() {
            out[i] = c.ctype;
        }
        self.n_columns
    }
}

impl TableDefBuilder {
    pub(crate) fn set_column_key_name(
        &mut self,
        column: usize,
        name: SqlName,
    ) -> Result<(), SqlError> {
        if self.n_inline_key_names > MAX_COLUMNS {
            return Err(sql_err!(
                sqlstate::DATA_EXCEPTION,
                "invalid inline key name count"
            ));
        }
        let attribute = self.attributes.number(column).ok_or_else(|| {
            sql_err!(
                sqlstate::DATA_EXCEPTION,
                "inline key has no stable column number"
            )
        })?;
        if let Some(key) = self.inline_key_names[..self.n_inline_key_names]
            .iter_mut()
            .find(|key| key.attribute == attribute)
        {
            key.name = name;
            return Ok(());
        }
        if self.n_inline_key_names == MAX_COLUMNS {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "inline key names exceed the column reservation"
            ));
        }
        self.inline_key_names[self.n_inline_key_names] = InlineKeyName { attribute, name };
        self.n_inline_key_names += 1;
        Ok(())
    }

    pub(crate) fn take_column_key_name(&mut self, column: usize) -> Option<SqlName> {
        let attribute = self.attributes.number(column)?;
        let position = self.inline_key_names[..self.n_inline_key_names]
            .iter()
            .position(|key| key.attribute == attribute)?;
        let name = self.inline_key_names[position].name;
        self.inline_key_names
            .copy_within(position + 1..self.n_inline_key_names, position);
        self.n_inline_key_names -= 1;
        self.inline_key_names[self.n_inline_key_names] = InlineKeyName::EMPTY;
        Some(name)
    }

    pub(crate) fn retain_active_inline_key_names(&mut self) -> Result<(), SqlError> {
        if self.n_inline_key_names > MAX_COLUMNS {
            return Err(sql_err!(
                sqlstate::DATA_EXCEPTION,
                "invalid inline key name count"
            ));
        }
        let mut count = 0;
        for position in 0..self.n_inline_key_names {
            let key = self.inline_key_names[position];
            if self
                .attribute_column(key.attribute)
                .is_some_and(|column| self.columns[column].primary || self.columns[column].unique)
            {
                self.inline_key_names[count] = key;
                count += 1;
            }
        }
        self.inline_key_names[count..self.n_inline_key_names].fill(InlineKeyName::EMPTY);
        self.n_inline_key_names = count;
        Ok(())
    }

    /// Copies an admitted definition into bounded edit or codec scratch.
    pub(crate) fn from_definition<B: DefinitionBacking>(source: &TableDefinition<B>) -> Self {
        let mut result = Self::empty();
        result.type_inputs = source.type_inputs.as_ref().clone();
        let attribute_count = usize::from(source.attributes.count);
        result.schema = source.schema;
        result.name = source.name;
        result.kind = source.kind;
        result.persistence = source.persistence;
        result.on_commit = source.on_commit;
        result.access_method = source.access_method;
        result.storage_options = source.storage_options;
        result.tablespace = source.tablespace;
        result.n_columns = source.n_columns;
        result.not_null_name_edits = source.not_null_name_edits;
        result.n_inline_key_names = source.n_inline_key_names;
        result.n_uniques = source.n_uniques;
        result.n_checks = source.n_checks;
        result.n_fkeys = source.n_fkeys;
        result.n_exclusions = source.n_exclusions;
        result.has_toast = source.has_toast;
        result.toast_index_identity = source.toast_index_identity;
        result.has_rules = source.has_rules;
        result.row_level_security = source.row_level_security;
        result.replica_identity = source.replica_identity;
        result.key_index_marks = source.key_index_marks;
        result.inheritance = source.inheritance;
        result.type_membership = source.type_membership;
        result.partition = source.partition;
        result.columns[..source.n_columns]
            .copy_from_slice(&source.columns.as_ref()[..source.n_columns]);
        result.not_null_names[..source.n_columns]
            .copy_from_slice(&source.not_null_names.as_ref()[..source.n_columns]);
        result.attribute_identities[..attribute_count]
            .copy_from_slice(&source.attribute_identities.as_ref()[..attribute_count]);
        result.inline_index_identities[..attribute_count]
            .copy_from_slice(&source.inline_index_identities.as_ref()[..attribute_count]);
        result.inline_constraint_identities[..attribute_count]
            .copy_from_slice(&source.inline_constraint_identities.as_ref()[..attribute_count]);
        result.inline_key_names[..source.n_inline_key_names]
            .copy_from_slice(source.inline_key_names());
        result.uniques[..source.n_uniques]
            .copy_from_slice(&source.uniques.as_ref()[..source.n_uniques]);
        result.checks[..source.n_checks]
            .copy_from_slice(&source.checks.as_ref()[..source.n_checks]);
        result.fkeys[..source.n_fkeys].copy_from_slice(&source.fkeys.as_ref()[..source.n_fkeys]);
        result.exclusions[..source.n_exclusions]
            .copy_from_slice(&source.exclusions.as_ref()[..source.n_exclusions]);
        result.n_expression_dependencies = source.n_expression_dependencies;
        result.expression_dependencies[..source.n_expression_dependencies]
            .copy_from_slice(source.expression_dependencies());
        result.attributes =
            column_attributes::ColumnAttributes::from_attributes(&source.attributes);
        result
    }

    /// Reserves the complete immutable candidate before its caller publishes it.
    pub(crate) fn freeze(
        &self,
        pool: &std::sync::Arc<crate::mem::lease_pool::LeasePool>,
    ) -> Result<TableDef, SqlError> {
        let attribute_count = usize::from(self.attributes.count);
        if self.n_columns > MAX_COLUMNS
            || attribute_count > MAX_RELATION_COLUMNS
            || self.n_inline_key_names > MAX_COLUMNS
            || self.n_uniques > MAX_UNIQUES
            || self.n_checks > MAX_CHECKS
            || self.n_fkeys > MAX_FKEYS
            || self.n_exclusions > MAX_EXCLUSIONS
            || self.n_expression_dependencies > MAX_TABLE_EXPRESSION_DEPENDENCIES
        {
            return Err(sql_err!(
                sqlstate::DATA_EXCEPTION,
                "invalid table definition slice count"
            ));
        }
        let exhausted = |error: crate::mem::lease_pool::LeaseError| {
            sql_err!(sqlstate::PROGRAM_LIMIT_EXCEEDED, "{}", error)
        };
        Ok(TableDefinition {
            type_inputs: self.type_inputs.clone(),
            schema: self.schema,
            name: self.name,
            kind: self.kind,
            persistence: self.persistence,
            on_commit: self.on_commit,
            access_method: self.access_method,
            storage_options: self.storage_options,
            tablespace: self.tablespace,
            n_columns: self.n_columns,
            not_null_name_edits: self.not_null_name_edits,
            n_inline_key_names: self.n_inline_key_names,
            n_uniques: self.n_uniques,
            n_checks: self.n_checks,
            n_fkeys: self.n_fkeys,
            n_exclusions: self.n_exclusions,
            n_expression_dependencies: self.n_expression_dependencies,
            has_toast: self.has_toast,
            toast_index_identity: self.toast_index_identity,
            has_rules: self.has_rules,
            row_level_security: self.row_level_security,
            replica_identity: self.replica_identity,
            key_index_marks: self.key_index_marks,
            inheritance: self.inheritance,
            type_membership: self.type_membership,
            partition: self.partition,
            columns: pool
                .copy_slice(&self.columns[..self.n_columns])
                .map_err(exhausted)?,
            not_null_names: pool
                .copy_slice(&self.not_null_names[..self.n_columns])
                .map_err(exhausted)?,
            attribute_identities: pool
                .copy_slice(&self.attribute_identities[..attribute_count])
                .map_err(exhausted)?,
            inline_index_identities: pool
                .copy_slice(&self.inline_index_identities[..attribute_count])
                .map_err(exhausted)?,
            inline_constraint_identities: pool
                .copy_slice(&self.inline_constraint_identities[..attribute_count])
                .map_err(exhausted)?,
            inline_key_names: pool
                .copy_slice(&self.inline_key_names[..self.n_inline_key_names])
                .map_err(exhausted)?,
            uniques: pool
                .copy_slice(&self.uniques[..self.n_uniques])
                .map_err(exhausted)?,
            checks: pool
                .copy_slice(&self.checks[..self.n_checks])
                .map_err(exhausted)?,
            fkeys: pool
                .copy_slice(&self.fkeys[..self.n_fkeys])
                .map_err(exhausted)?,
            exclusions: pool
                .copy_slice(&self.exclusions[..self.n_exclusions])
                .map_err(exhausted)?,
            expression_dependencies: pool
                .copy_slice(&self.expression_dependencies[..self.n_expression_dependencies])
                .map_err(exhausted)?,
            attributes: column_attributes::ColumnAttributes {
                count: self.attributes.count,
                slots: pool
                    .copy_slice(&self.attributes.slots[..attribute_count])
                    .map_err(exhausted)?,
            },
        })
    }

    /// A table with a name and no columns or constraints, for spread-init of
    /// the constraint arrays at construction sites.
    pub const fn empty() -> Self {
        Self {
            type_inputs: StoredTypeInputs::EMPTY,
            schema: SqlName::EMPTY,
            name: SqlName::EMPTY,
            kind: TableKind::Local,
            persistence: RelationPersistence::Permanent,
            on_commit: OnCommitAction::PreserveRows,
            access_method: TableAccessMethod::Heap,
            storage_options: TableStorageOptions::DEFAULT,
            tablespace: 0,
            columns: [ColumnMeta::EMPTY; MAX_COLUMNS],
            n_columns: 0,
            not_null_names: [None; MAX_COLUMNS],
            not_null_name_edits: ColumnSet::EMPTY,
            attribute_identities: [AttributeIdentities::NONE; MAX_RELATION_COLUMNS],
            attributes: column_attributes::ColumnAttributes::<InlineDefinition>::EMPTY,
            inline_index_identities: [None; MAX_RELATION_COLUMNS],
            inline_constraint_identities: [None; MAX_RELATION_COLUMNS],
            inline_key_names: [InlineKeyName::EMPTY; MAX_COLUMNS],
            n_inline_key_names: 0,
            uniques: [UniqueKey::EMPTY; MAX_UNIQUES],
            n_uniques: 0,
            checks: [CheckConstraint::EMPTY; MAX_CHECKS],
            n_checks: 0,
            fkeys: [ForeignKey::EMPTY; MAX_FKEYS],
            n_fkeys: 0,
            exclusions: [ExclusionConstraint::EMPTY; MAX_EXCLUSIONS],
            n_exclusions: 0,
            expression_dependencies: [ExpressionDependency::EMPTY;
                MAX_TABLE_EXPRESSION_DEPENDENCIES],
            n_expression_dependencies: 0,
            has_toast: false,
            toast_index_identity: None,
            has_rules: false,
            row_level_security: RowLevelSecurityState::DISABLED,
            replica_identity: ReplicaIdentityMode::DEFAULT,
            key_index_marks: KeyIndexMarks::NONE,
            inheritance: TableInheritance::NONE,
            type_membership: TableTypeMembership::NONE,
            partition: PartitionDef::NONE,
        }
    }
}

