    fn pending_owner_other_than(&self, txid: u32) -> Option<u32> {
        [
            self.ddl_state.pending_txid(),
            self.pending.map(|pending| pending.txid),
            self.ownership.pending.map(|pending| pending.txid),
        ]
        .into_iter()
        .flatten()
        .find(|owner| *owner != txid)
    }
