#[derive(Clone, Copy, Debug)]
pub(crate) struct AclEntry {
    pub object: AccessObject,
    pub grantee: u16,
    pub grantor: u16,
    pub privileges: PrivilegeSet,
    pub grant_options: PrivilegeSet,
    pub live: bool,
    pub pending: Option<PendingObjectAcl>,
    pub order: Option<core::num::NonZeroU64>,
}

impl AclEntry {
    fn retire(&mut self) {
        self.object.slot = u16::MAX;
        self.grantee = u16::MAX;
        self.grantor = u16::MAX;
        self.privileges = PrivilegeSet::NONE;
        self.grant_options = PrivilegeSet::NONE;
        self.live = false;
        self.pending = None;
        self.order = None;
    }
}

