/// The four PostgreSQL ACL catalogs share one synchronization boundary.
/// Cross-catalog ownership and dependency changes therefore observe complete
/// privilege images, while every fixed vector retains its startup capacity.
struct AclCatalog {
    objects: FixedVec<AclEntry>,
    next_object_order: u64,
    next_object_change: u64,
    columns: FixedVec<ColumnAclEntry>,
    defaults: FixedVec<DefaultAclEntry>,
    parameters: FixedVec<ParameterAclEntry>,
    parameter_rows: ParameterAclRows,
}

struct ObjectAclIter<'a> {
    storage: &'a Storage,
    next_slot: usize,
    checkpoint: bool,
}

impl Iterator for ObjectAclIter<'_> {
    type Item = (usize, AclEntry);

    fn next(&mut self) -> Option<Self::Item> {
        loop {
            let (slot, entry) = {
                let catalog = self
                    .storage
                    .acl_catalog
                    .lock()
                    .expect("ACL catalog lock poisoned");
                if self.next_slot >= catalog.objects.len() {
                    return None;
                }
                let slot = self.next_slot;
                self.next_slot += 1;
                (slot, catalog.objects[slot])
            };
            let include = if self.checkpoint {
                entry.object.slot != u16::MAX
                    && !self.storage.access_object_is_temporary(entry.object, 0)
                    && entry.order.is_some()
                    && (entry.live
                        || (entry.grantee == entry.grantor
                            && usize::from(entry.grantee)
                                == self.storage.object_owner(entry.object, 0)))
            } else {
                entry.object.slot != u16::MAX
                    && self.storage.access_object_in_current_database(entry.object)
            };
            if include {
                return Some((slot, entry));
            }
        }
    }
}

struct ColumnAclIter<'a> {
    storage: &'a Storage,
    next_slot: usize,
    checkpoint: bool,
}

impl Iterator for ColumnAclIter<'_> {
    type Item = (usize, ColumnAclEntry);

    fn next(&mut self) -> Option<Self::Item> {
        loop {
            let (slot, entry) = {
                let catalog = self
                    .storage
                    .acl_catalog
                    .lock()
                    .expect("ACL catalog lock poisoned");
                if self.next_slot >= catalog.columns.len() {
                    return None;
                }
                let slot = self.next_slot;
                self.next_slot += 1;
                (slot, catalog.columns[slot])
            };
            let include = if self.checkpoint {
                entry.live
                    && !self
                        .storage
                        .access_object_is_temporary(entry.target.relation, 0)
            } else {
                entry.target.relation.slot != u16::MAX
                    && self
                        .storage
                        .access_object_in_current_database(entry.target.relation)
            };
            if include {
                return Some((slot, entry));
            }
        }
    }
}

struct DefaultAclIter<'a> {
    catalog: &'a Mutex<AclCatalog>,
    database: Option<DatabaseOid>,
    next_slot: usize,
}

impl Iterator for DefaultAclIter<'_> {
    type Item = (usize, DefaultAclEntry);

    fn next(&mut self) -> Option<Self::Item> {
        let catalog = self.catalog.lock().expect("ACL catalog lock poisoned");
        while self.next_slot < catalog.defaults.len() {
            let slot = self.next_slot;
            self.next_slot += 1;
            let entry = catalog.defaults[slot];
            let include = self.database.map_or(entry.committed.is_some(), |database| {
                entry.database == database
            });
            if include {
                return Some((slot, entry));
            }
        }
        None
    }
}

/// Startup-bounded PostgreSQL role catalog. Role metadata is catalog state and
/// therefore follows the same transaction/WAL/manifest lifecycle as schemas;
/// it never lives in a process-global authentication side table.
/// Role slots use `u16::MAX` for PUBLIC, leaving indices 0..65534 available.
/// Largest `max_roles`: with the predefined roles, every slot stays below the
/// PUBLIC sentinel.
pub(crate) const MAX_ROLE_CATALOG_SLOTS: usize = u16::MAX as usize - PREDEFINED_ROLE_COUNT;
/// Largest `max_role_memberships`; the initdb memberships take extra slots.
pub(crate) const MAX_ROLE_MEMBERSHIP_CATALOG_SLOTS: usize =
    u16::MAX as usize - INITDB_MEMBERSHIPS.len();
pub(crate) const MAX_ROLE_SETTING_CATALOG_SLOTS: usize = u16::MAX as usize;
pub(crate) const MAX_SYSTEM_SETTINGS: usize = 32;
pub(crate) const ROLE_SETTING_VALUE_MAX: usize = 256;
pub(crate) const ROLE_PASSWORD_MAX: usize = 128;
pub(crate) const ROLE_VALID_UNTIL_MAX: usize = 64;

/// An imported PostgreSQL MD5 verifier keeps its exact catalog bytes. The
/// role name is part of its derivation, so role rename clears this credential.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Md5Verifier {
    pub hash: [u8; 32],
}

impl Md5Verifier {
    pub fn derive(password: &str, role: &str) -> Option<Self> {
        let mut source = [0u8; ROLE_PASSWORD_MAX + 64];
        let len = password.len().checked_add(role.len())?;
        if len > source.len() {
            return None;
        }
        source[..password.len()].copy_from_slice(password.as_bytes());
        source[password.len()..len].copy_from_slice(role.as_bytes());
        let mut hash = [0u8; 32];
        crate::sql::md5::hex(&crate::sql::md5::digest(&source[..len]), &mut hash);
        Some(Self { hash })
    }
}

/// A role credential is a parsed durable authentication verifier. Plaintext
/// never reaches catalog, WAL, checkpoint, or object storage state.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum RoleCredential {
    Scram(crate::pg::auth::ScramServer),
    Md5(Md5Verifier),
}

