/// Copies comment text into a fixed buffer, or a loud error if it is longer
/// than [`COMMENT_MAX`] (never a silent truncation).
pub(crate) fn comment_stackstr(text: &str) -> Result<StackStr<COMMENT_MAX>, SqlError> {
    use core::fmt::Write;
    let mut stored = StackStr::<COMMENT_MAX>::new();
    let _ = write!(stored, "{text}");
    if stored.is_truncated() {
        return Err(sql_err!(
            sqlstate::PROGRAM_LIMIT_EXCEEDED,
            "comment exceeds {} bytes",
            COMMENT_MAX
        ));
    }
    Ok(stored)
}

/// The longest comment text we store. A longer `COMMENT ON` is a loud
/// `PROGRAM_LIMIT_EXCEEDED`, never a silent truncation (static-memory rule).
/// Sized so a `DdlUndo::CommentSet` (which carries a prior comment inline)
/// stays within the transaction undo log's largest pre-existing entry.
pub(crate) const COMMENT_MAX: usize = 192;

/// Which catalog a comment's object lives in. `Relation` covers every
/// `pg_class` object (table, view, materialized view, index, sequence — and a
/// column, via a non-zero `subid`); `Schema` covers `pg_namespace`; `Type`
/// covers built-in and user-defined rows of `pg_type`; `Tablespace` covers
/// shared `pg_tablespace` objects.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum CommentClass {
    Relation,
    Schema,
    Type,
    Tablespace,
    Extension,
    Trigger,
    Database,
    Collation,
    Conversion,
    EventTrigger,
    Rule,
    TextSearchParser,
    TextSearchTemplate,
    TextSearchDictionary,
    TextSearchConfiguration,
    LargeObject,
    Routine,
    Policy,
    Statistics,
    Publication,
    Subscription,
    Role,
    ForeignServer,
    Cast,
    Operator,
    OperatorFamily,
    OperatorClass,
    Constraint,
    ForeignDataWrapper,
    AccessMethod,
    ProceduralLanguage,
}

impl CommentClass {
    pub fn to_u8(self) -> u8 {
        match self {
            CommentClass::Relation => 0,
            CommentClass::Schema => 1,
            CommentClass::Type => 2,
            CommentClass::Tablespace => 3,
            CommentClass::Extension => 4,
            CommentClass::Trigger => 5,
            CommentClass::Database => 6,
            CommentClass::Collation => 7,
            CommentClass::Conversion => 8,
            CommentClass::EventTrigger => 9,
            CommentClass::Rule => 10,
            CommentClass::TextSearchParser => 11,
            CommentClass::TextSearchTemplate => 12,
            CommentClass::TextSearchDictionary => 13,
            CommentClass::TextSearchConfiguration => 14,
            CommentClass::LargeObject => 15,
            CommentClass::Routine => 16,
            CommentClass::Policy => 17,
            CommentClass::Statistics => 18,
            CommentClass::Publication => 19,
            CommentClass::Subscription => 20,
            CommentClass::Role => 21,
            CommentClass::ForeignServer => 22,
            CommentClass::Cast => 23,
            CommentClass::Operator => 24,
            CommentClass::OperatorFamily => 25,
            CommentClass::OperatorClass => 26,
            CommentClass::Constraint => 27,
            CommentClass::ForeignDataWrapper => 28,
            CommentClass::AccessMethod => 29,
            CommentClass::ProceduralLanguage => 30,
        }
    }

    pub fn from_u8(value: u8) -> Option<Self> {
        Some(match value {
            0 => CommentClass::Relation,
            1 => CommentClass::Schema,
            2 => CommentClass::Type,
            3 => CommentClass::Tablespace,
            4 => CommentClass::Extension,
            5 => CommentClass::Trigger,
            6 => CommentClass::Database,
            7 => CommentClass::Collation,
            8 => CommentClass::Conversion,
            9 => CommentClass::EventTrigger,
            10 => CommentClass::Rule,
            11 => CommentClass::TextSearchParser,
            12 => CommentClass::TextSearchTemplate,
            13 => CommentClass::TextSearchDictionary,
            14 => CommentClass::TextSearchConfiguration,
            15 => CommentClass::LargeObject,
            16 => CommentClass::Routine,
            17 => CommentClass::Policy,
            18 => CommentClass::Statistics,
            19 => CommentClass::Publication,
            20 => CommentClass::Subscription,
            21 => CommentClass::Role,
            22 => CommentClass::ForeignServer,
            23 => CommentClass::Cast,
            24 => CommentClass::Operator,
            25 => CommentClass::OperatorFamily,
            26 => CommentClass::OperatorClass,
            27 => CommentClass::Constraint,
            28 => CommentClass::ForeignDataWrapper,
            29 => CommentClass::AccessMethod,
            30 => CommentClass::ProceduralLanguage,
            _ => return None,
        })
    }
}

fn text_search_comment_class(kind: crate::sql::ast::TextSearchObjectKind) -> CommentClass {
    match kind {
        crate::sql::ast::TextSearchObjectKind::Parser => CommentClass::TextSearchParser,
        crate::sql::ast::TextSearchObjectKind::Template => CommentClass::TextSearchTemplate,
        crate::sql::ast::TextSearchObjectKind::Dictionary => CommentClass::TextSearchDictionary,
        crate::sql::ast::TextSearchObjectKind::Configuration => {
            CommentClass::TextSearchConfiguration
        }
    }
}

/// The kind of a relation, for `COMMENT ON` kind-checking.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum StoredRelKind {
    Table,
    View,
    Matview,
    Index,
    Sequence,
    ForeignTable,
}

/// A transaction's uncommitted comment write overlaying the committed `live`
/// text (catalog MVCC, mirroring `Table`'s row overlay): `text == None` is an
/// uncommitted removal.
#[derive(Clone, Copy, Debug)]
pub struct PendingComment {
    pub txid: u32,
    pub text: Option<StackStr<COMMENT_MAX>>,
    root: core::num::NonZeroU64,
}

#[derive(Clone, Copy, Debug)]
pub(crate) struct PendingCommentIdentity {
    txid: u32,
    schema: SqlName,
    name: SqlName,
}

/// A comment attached to a database object, keyed by `(class, schema, name,
/// subid)` — restart-stable, since object OIDs derive from catalog slots but
/// names do not. `subid` is 0 for object comments, a column number for column
/// comments, or the stable catalog OID for static and slot-addressed objects.
/// `live` is the committed text (`None` once removed), `pending` the owning
/// transaction's uncommitted overlay.
#[derive(Clone, Copy, Debug)]
pub struct CommentEntry {
    pub used: bool,
    pub(crate) database: Option<DatabaseOid>,
    pub class: CommentClass,
    pub schema: SqlName,
    pub name: SqlName,
    pub subid: u32,
    pub live: Option<StackStr<COMMENT_MAX>>,
    root: Option<core::num::NonZeroU64>,
    pub pending: Option<PendingComment>,
    pending_identity: Option<PendingCommentIdentity>,
    pending_drop: Option<PendingCommentDrop>,
}

#[derive(Clone, Copy, Debug)]
struct PendingCommentDrop {
    txid: u32,
    source: catalog_sources::CatalogObjectIdentity,
}

struct CommentCatalog {
    entries: FixedVec<CommentEntry>,
    next_root: core::num::NonZeroU64,
}

impl CommentCatalog {
    fn reserve_root(&mut self) -> Result<core::num::NonZeroU64, SqlError> {
        let root = self.next_root;
        self.next_root = root.checked_add(1).ok_or_else(|| {
            sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "comment tuple identity exhausted"
            )
        })?;
        Ok(root)
    }

    fn reap(&mut self, slot: usize) {
        let comment = &mut self.entries[slot];
        if comment.live.is_none()
            && comment.pending.is_none()
            && comment.pending_identity.is_none()
            && comment.pending_drop.is_none()
        {
            *comment = CommentEntry::empty();
        }
    }
}

struct LiveCommentIter<'a> {
    catalog: &'a Mutex<CommentCatalog>,
    database: DatabaseOid,
    next_slot: usize,
}

struct CheckpointCommentIter<'a> {
    catalog: &'a Mutex<CommentCatalog>,
    next_slot: usize,
}

impl Iterator for CheckpointCommentIter<'_> {
    type Item = CommentEntry;

    fn next(&mut self) -> Option<Self::Item> {
        let catalog = self.catalog.lock().expect("comment catalog lock poisoned");
        while self.next_slot < catalog.entries.len() {
            let slot = self.next_slot;
            self.next_slot += 1;
            let comment = catalog.entries[slot];
            if comment.used
                && comment.live.is_some()
                && !comment.schema.as_str().starts_with("pg_temp_")
            {
                return Some(comment);
            }
        }
        None
    }
}

impl Iterator for LiveCommentIter<'_> {
    type Item = CommentEntry;

    fn next(&mut self) -> Option<Self::Item> {
        let catalog = self.catalog.lock().expect("comment catalog lock poisoned");
        while self.next_slot < catalog.entries.len() {
            let slot = self.next_slot;
            self.next_slot += 1;
            let comment = catalog.entries[slot];
            if comment.used
                && comment.live.is_some()
                && comment
                    .database
                    .is_none_or(|database| database == self.database)
            {
                return Some(comment);
            }
        }
        None
    }
}

pub(crate) struct CatalogComment {
    pub(crate) class: CommentClass,
    pub(crate) schema: SqlName,
    pub(crate) name: SqlName,
    pub(crate) subid: u32,
    pub(crate) text: Option<StackStr<COMMENT_MAX>>,
    pub(crate) private: bool,
    pub(crate) root: Option<core::num::NonZeroU64>,
    pub(crate) lookup_transaction: u32,
}

struct CatalogCommentIter<'a> {
    catalog: &'a Mutex<CommentCatalog>,
    database: DatabaseOid,
    txid: u32,
    next_slot: usize,
}

impl Iterator for CatalogCommentIter<'_> {
    type Item = CatalogComment;

    fn next(&mut self) -> Option<Self::Item> {
        let catalog = self.catalog.lock().expect("comment catalog lock poisoned");
        while let Some(comment) = catalog.entries.get(self.next_slot).copied() {
            self.next_slot += 1;
            if !comment.used
                || comment
                    .database
                    .is_some_and(|database| database != self.database)
            {
                continue;
            }
            let removed = self.txid != 0
                && comment
                    .pending_drop
                    .is_some_and(|pending| pending.txid == self.txid);
            let pending = comment
                .pending
                .filter(|pending| self.txid != 0 && pending.txid == self.txid);
            let identity = comment
                .pending_identity
                .filter(|identity| self.txid != 0 && identity.txid == self.txid);
            let private = removed || pending.is_some();
            let text = if removed {
                None
            } else {
                pending.map_or(comment.live, |pending| pending.text)
            };
            if text.is_none() && !private {
                continue;
            }
            return Some(CatalogComment {
                class: comment.class,
                schema: if removed {
                    comment.schema
                } else {
                    identity.map_or(comment.schema, |identity| identity.schema)
                },
                name: if removed {
                    comment.name
                } else {
                    identity.map_or(comment.name, |identity| identity.name)
                },
                subid: comment.subid,
                text,
                private,
                root: pending.map(|pending| pending.root).or(comment.root),
                lookup_transaction: if removed { 0 } else { self.txid },
            });
        }
        None
    }
}

impl CommentEntry {
    fn empty() -> Self {
        Self {
            used: false,
            database: None,
            class: CommentClass::Relation,
            schema: SqlName::EMPTY,
            name: SqlName::EMPTY,
            subid: 0,
            live: None,
            root: None,
            pending: None,
            pending_identity: None,
            pending_drop: None,
        }
    }

    fn matches(
        &self,
        database: Option<DatabaseOid>,
        class: CommentClass,
        schema: &str,
        name: &str,
        subid: u32,
    ) -> bool {
        self.used
            && self.database == database
            && self.class == class
            && self.subid == subid
            && self.name.as_str() == name
            && self.schema.as_str() == schema
    }

    fn matches_to(
        &self,
        database: Option<DatabaseOid>,
        class: CommentClass,
        schema: &str,
        name: &str,
        subid: u32,
        txid: u32,
    ) -> bool {
        self.used
            && !self
                .pending_drop
                .is_some_and(|pending| pending.txid == txid)
            && self.database == database
            && self.class == class
            && self.subid == subid
            && self
                .pending_identity
                .filter(|identity| identity.txid == txid)
                .map_or(self.schema, |identity| identity.schema)
                .as_str()
                == schema
            && self
                .pending_identity
                .filter(|identity| identity.txid == txid)
                .map_or(self.name, |identity| identity.name)
                .as_str()
                == name
    }
}

/// One effective namespace: a live user schema or a built-in virtual schema.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum PathEntry {
    Schema(u16),
    Catalog,
    InformationSchema,
    Toast,
}

/// PostgreSQL protects relation-backed objects in pg_catalog separately from schema ACLs.
#[derive(Clone, Copy, PartialEq, Eq)]
pub enum SchemaObjectKind {
    Relation,
    NonRelation,
}

/// A canonical search path cannot contain more non-empty names than this:
/// each name needs at least one byte and adjacent names need a separator. One
/// additional entry admits the implicit `pg_catalog` prefix.
pub(crate) const MAX_PATH_ENTRIES: usize = crate::sql::guc::SEARCH_PATH_BYTES.div_ceil(2) + 1;

/// The effective search path of the running statement: the visible schemas
/// the session's `search_path` names, in order, with `pg_catalog` interleaved
/// at its explicit position or implicitly first. Set by the engine before each
/// statement (and swapped while a view body — which resolves under its
/// creator's path — expands); every name resolution reads it.
#[derive(Clone, Copy)]
pub struct PathContext {
    entries: [PathEntry; MAX_PATH_ENTRIES],
    n: usize,
    /// An explicit pg_catalog participates in current_schema and creation;
    /// the implicit prefix is only a lookup namespace.
    explicit_catalog: bool,
}

impl PathContext {
    /// A path of exactly `public` (slot 0) with implicit pg_catalog, the
    /// state before any session context is computed (journal replay, tests).
    pub const fn public_only() -> Self {
        let mut entries = [PathEntry::Catalog; MAX_PATH_ENTRIES];
        entries[0] = PathEntry::Catalog;
        entries[1] = PathEntry::Schema(0);
        PathContext {
            entries,
            n: 2,
            explicit_catalog: false,
        }
    }

    const fn public_schema(slot: u16) -> Self {
        let mut entries = [PathEntry::Catalog; MAX_PATH_ENTRIES];
        entries[1] = PathEntry::Schema(slot);
        Self {
            entries,
            n: 2,
            explicit_catalog: false,
        }
    }

    pub fn entries(&self) -> &[PathEntry] {
        &self.entries[..self.n]
    }

    pub fn explicit_catalog(&self) -> bool {
        self.explicit_catalog
    }

    /// The first explicit namespace is the creation target, including read-only schemas.
    pub fn creation_target(&self) -> Option<PathEntry> {
        self.entries()
            .get(usize::from(!self.explicit_catalog))
            .copied()
    }

    /// Catalog sources retain which virtual namespace won name resolution.
    pub(crate) fn catalog_namespace(
        &self,
        qualifier: Option<&str>,
        name: &str,
    ) -> Option<&'static str> {
        match qualifier {
            Some("pg_catalog") => Some("pg_catalog"),
            Some("information_schema")
                if crate::sql::catalog::is_catalog_relation(qualifier, name) =>
            {
                Some("information_schema")
            }
            Some(_) => None,
            None => self.entries().iter().find_map(|entry| match entry {
                PathEntry::Catalog if crate::sql::catalog::is_catalog_relation(None, name) => {
                    Some("pg_catalog")
                }
                PathEntry::InformationSchema
                    if crate::sql::catalog::is_catalog_relation(
                        Some("information_schema"),
                        name,
                    ) =>
                {
                    Some("information_schema")
                }
                _ => None,
            }),
        }
    }
}

thread_local! {
    static EXECUTION_PATH: Cell<PathContext> = const { Cell::new(PathContext::public_only()) };
    static EXECUTION_VISIBILITY: Cell<VisibilityContext> =
        const { Cell::new(VisibilityContext::all()) };
}

#[derive(Clone, Copy)]
struct VisibilityContext {
    /// A row's own-transaction pending change is visible only when its command
    /// identifier precedes this value. `SNAPSHOT_ALL` sees every own write.
    read_snapshot: u32,
    /// Greatest durable commit LSN visible to the running statement.
    commit_snapshot: u64,
    analyzing: bool,
}

impl VisibilityContext {
    const fn all() -> Self {
        Self {
            read_snapshot: SNAPSHOT_ALL,
            commit_snapshot: u64::MAX,
            analyzing: false,
        }
    }
}

pub(crate) fn execution_path() -> PathContext {
    EXECUTION_PATH.with(Cell::get)
}

pub(crate) fn information_schema_on_path() -> bool {
    execution_path()
        .entries()
        .contains(&PathEntry::InformationSchema)
}

pub(crate) fn replace_execution_path(path: PathContext) -> PathContext {
    EXECUTION_PATH.with(|current| current.replace(path))
}

std::thread_local! {
    static NO_FORCE_ROW_SECURITY: core::cell::Cell<bool> = const { core::cell::Cell::new(false) };
}

/// Restores the caller's row security forcing when dropped.
pub(crate) struct NoForceRowSecurityScope(bool);

impl Drop for NoForceRowSecurityScope {
    fn drop(&mut self) {
        NO_FORCE_ROW_SECURITY.with(|current| current.set(self.0));
    }
}

/// Exempts a table's owner from `FORCE ROW LEVEL SECURITY` while the scope
/// lives, as PostgreSQL's referential queries run (`SECURITY_NOFORCE_RLS`).
pub(crate) fn enter_no_force_row_security() -> NoForceRowSecurityScope {
    NoForceRowSecurityScope(NO_FORCE_ROW_SECURITY.with(|current| current.replace(true)))
}

fn execution_visibility() -> VisibilityContext {
    EXECUTION_VISIBILITY.with(Cell::get)
}

fn replace_execution_visibility(visibility: VisibilityContext) -> VisibilityContext {
    EXECUTION_VISIBILITY.with(|current| current.replace(visibility))
}

/// Restore the caller's complete read context on every exit, on this thread only.
pub(crate) struct ReadSnapshotScope {
    previous: VisibilityContext,
    thread: core::marker::PhantomData<std::rc::Rc<()>>,
}

/// Saved visibility contains no worker borrow; its transaction retains the
/// reader lease while execution is parked.
pub(crate) struct SavedReadSnapshot(VisibilityContext);

impl ReadSnapshotScope {
    pub(crate) fn capture_current(&self) -> SavedReadSnapshot {
        SavedReadSnapshot(execution_visibility())
    }
}

impl SavedReadSnapshot {
    pub(crate) fn resume(self) -> ReadSnapshotScope {
        ReadSnapshotScope {
            previous: replace_execution_visibility(self.0),
            thread: core::marker::PhantomData,
        }
    }
}

impl Drop for ReadSnapshotScope {
    fn drop(&mut self) {
        replace_execution_visibility(self.previous);
    }
}

/// What a relation name resolved to.
#[derive(Clone, Copy, PartialEq, Eq)]
pub enum ResolvedRelation {
    Table(usize),
    View(usize),
    /// A `pg_catalog` / `information_schema` relation (synthesized rows).
    Catalog,
}

/// Relations and accounts have separate lock identities. Account identifiers
/// remain distinct when a catalog position is reused.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum ObjectLockTarget {
    Table(usize),
    View(usize),
    Role(RoleOid),
}

impl From<RuleTarget> for ObjectLockTarget {
    fn from(target: RuleTarget) -> Self {
        match target {
            RuleTarget::Table(slot) => Self::Table(usize::from(slot)),
            RuleTarget::View(slot) => Self::View(usize::from(slot)),
        }
    }
}

fn object_lock_modes_conflict(left: u8, right: u8) -> bool {
    for left_index in 0..8 {
        if left & (1 << left_index) == 0 {
            continue;
        }
        for right_index in 0..8 {
            if right & (1 << right_index) != 0 && mode_conflicts(left_index, right_index) {
                return true;
            }
        }
    }
    false
}

fn mode_conflicts(left: u8, right: u8) -> bool {
    use crate::sql::ast::TableLockMode::*;
    let left = match left {
        0 => AccessShare,
        1 => RowShare,
        2 => RowExclusive,
        3 => ShareUpdateExclusive,
        4 => Share,
        5 => ShareRowExclusive,
        6 => Exclusive,
        _ => AccessExclusive,
    };
    let right = match right {
        0 => AccessShare,
        1 => RowShare,
        2 => RowExclusive,
        3 => ShareUpdateExclusive,
        4 => Share,
        5 => ShareRowExclusive,
        6 => Exclusive,
        _ => AccessExclusive,
    };
    matches!(
        (left, right),
        (AccessShare, AccessExclusive)
            | (RowShare, Exclusive | AccessExclusive)
            | (
                RowExclusive,
                Share | ShareRowExclusive | Exclusive | AccessExclusive
            )
            | (
                ShareUpdateExclusive,
                ShareUpdateExclusive | Share | ShareRowExclusive | Exclusive | AccessExclusive
            )
            | (
                Share,
                RowExclusive
                    | ShareUpdateExclusive
                    | ShareRowExclusive
                    | Exclusive
                    | AccessExclusive
            )
            | (
                ShareRowExclusive,
                RowExclusive
                    | ShareUpdateExclusive
                    | Share
                    | ShareRowExclusive
                    | Exclusive
                    | AccessExclusive
            )
            | (
                Exclusive,
                RowShare
                    | RowExclusive
                    | ShareUpdateExclusive
                    | Share
                    | ShareRowExclusive
                    | Exclusive
                    | AccessExclusive
            )
            | (AccessExclusive, _)
    ) || matches!(right, AccessExclusive)
}

fn object_lock_capacity(config: &Config) -> usize {
    (config.max_connections as usize)
        .saturating_add(config.max_prepared_transactions)
        .saturating_mul(
            table_slot_capacity(config)
                .saturating_add(config.max_views)
                .saturating_add(config.max_roles),
        )
        .saturating_add(config.max_connections as usize)
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum ObjectLockOwner {
    Transaction(u32),
    Session { connection: i32, acquisition: u64 },
}

#[derive(Clone, Copy)]
pub(crate) struct ReindexTable {
    pub slot: usize,
    pub created_at: u64,
}

#[derive(Clone, Copy)]
pub(crate) struct IndexReplacement {
    pub old_slot: usize,
    pub old_created_at: u64,
    pub new_slot: usize,
    pub new_created_at: u64,
    pub table: usize,
}

/// One command's hold on a specific table lifetime across internal commits.
pub(crate) struct SessionTableLock {
    owner: ObjectLockOwner,
    table: usize,
    created_at: u64,
    locks: std::sync::Arc<Mutex<LockState>>,
}

impl core::fmt::Debug for SessionTableLock {
    fn fmt(&self, formatter: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        formatter
            .debug_struct("SessionTableLock")
            .field("owner", &self.owner)
            .field("table", &self.table)
            .field("created_at", &self.created_at)
            .finish()
    }
}

impl Drop for SessionTableLock {
    fn drop(&mut self) {
        let mut locks = self.locks.lock().expect("lock state lock poisoned");
        if let Some(index) = locks.table.iter().position(|lock| {
            lock.owner == self.owner && lock.relation == ObjectLockTarget::Table(self.table)
        }) {
            let owner = locks.table.swap_remove(index).wait_owner;
            locks.row.resource_released(owner);
        }
    }
}

#[derive(Clone, Copy)]
struct ObjectLock {
    owner: ObjectLockOwner,
    wait_owner: crate::sql::lock::WaitOwner,
    relation: ObjectLockTarget,
    /// Acquisition sequence for each table-lock mode. PostgreSQL permits a
    /// transaction to hold multiple incomparable modes on one relation.
    modes: [u64; 8],
}

impl ObjectLock {
    fn mask(&self) -> u8 {
        self.modes
            .iter()
            .enumerate()
            .fold(0, |mask, (index, sequence)| {
                mask | u8::from(*sequence != 0) << index
            })
    }
}

struct LockState {
    table: FixedVec<ObjectLock>,
    row: crate::sql::lock::LockManager,
    advisory: crate::sql::lock::AdvisoryLockManager,
    sequence: u64,
}

pub(crate) struct AdvisoryPositionAdmission {
    locks: std::sync::Arc<Mutex<LockState>>,
    prior: Option<crate::sql::lock::AdvisoryPositionRestore>,
}

/// Keeps the connection's existing lock registry available while the engine
/// mutably borrows storage. Cloning the handle allocates no registry or pool.
pub(crate) struct AdvisoryJournal {
    locks: std::sync::Arc<Mutex<LockState>>,
    connection_id: i32,
}

impl AdvisoryJournal {
    pub(crate) fn position(&self) -> crate::sql::lock::AdvisoryStatementPosition {
        self.locks
            .lock()
            .expect("lock state is not poisoned")
            .advisory
            .statement_position(self.connection_id)
    }

    pub(crate) fn resume_position(
        &self,
        saved: crate::sql::lock::AdvisoryStatementPosition,
        tail: crate::sql::lock::AdvisoryPositionTail,
    ) -> Result<AdvisoryPositionAdmission, SqlError> {
        let prior = self
            .locks
            .lock()
            .expect("lock state is not poisoned")
            .advisory
            .resume_position(saved, self.connection_id, tail)?;
        Ok(AdvisoryPositionAdmission {
            locks: std::sync::Arc::clone(&self.locks),
            prior: Some(prior),
        })
    }
}

impl AdvisoryPositionAdmission {
    pub(crate) fn commit(&mut self) {
        self.prior = None;
    }
}

impl Drop for AdvisoryPositionAdmission {
    fn drop(&mut self) {
        if let Some(prior) = self.prior.take() {
            self.locks
                .lock()
                .expect("lock state is not poisoned")
                .advisory
                .restore_position(prior);
        }
    }
}

impl LockState {
    fn next_sequence(&mut self) -> Result<u64, SqlError> {
        self.sequence = self.sequence.checked_add(1).ok_or_else(|| {
            sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "lock acquisition identity is exhausted"
            )
        })?;
        Ok(self.sequence)
    }
}

#[derive(Clone, Copy)]
struct ReplayTableRewrite {
    table: usize,
    preserve_rows: bool,
    column_mapping: [u16; MAX_COLUMNS],
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) struct PreparedTransactionCatalogEntry {
    pub transaction_id: u32,
    pub gid: StackStr<199>,
    pub prepared_at: i64,
    pub owner: RoleOid,
    pub database: DatabaseOid,
    pub first_lsn: u64,
    pub prepared_lsn: u64,
}

struct PreparedTransactionCatalog {
    entries: FixedVec<PreparedTransactionCatalogEntry>,
    candidate: FixedVec<PreparedTransactionCatalogEntry>,
}

impl PreparedTransactionCatalog {
    fn validate_entry(
        entries: &[PreparedTransactionCatalogEntry],
        entry: PreparedTransactionCatalogEntry,
    ) -> Result<(), SqlError> {
        if entry.transaction_id == 0
            || entry.first_lsn == 0
            || entry.prepared_lsn < entry.first_lsn
            || entry.gid.is_truncated()
            || entry.gid.as_str().as_bytes().contains(&0)
        {
            return Err(sql_err!(
                sqlstate::INVALID_PARAMETER_VALUE,
                "invalid prepared transaction catalog metadata"
            ));
        }
        if entries.iter().any(|retained| {
            retained.transaction_id == entry.transaction_id || retained.gid == entry.gid
        }) {
            return Err(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "duplicate prepared transaction catalog identity"
            ));
        }
        Ok(())
    }
}

/// One transaction-owned PostgreSQL foreign session. This identity prevents a
/// remote transaction from being reused by another local transaction or
/// endpoint.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct ForeignSession {
    transaction_id: u32,
    endpoint: crate::pg::replication_client::ConnectionInfo,
    timeout: std::time::Duration,
    active: bool,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct ForeignSessionId(usize);

impl ForeignSessionId {
    const fn index(self) -> usize {
        self.0
    }
}

/// One validated ownership token for a fixed foreign-session slot.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) struct ForeignSessionLease {
    session_id: ForeignSessionId,
    transaction_id: u32,
    endpoint: crate::pg::replication_client::ConnectionInfo,
}

impl ForeignSessionLease {
    pub(crate) const fn transaction_id(self) -> u32 {
        self.transaction_id
    }
}

struct ForeignSessionSlot {
    client: crate::pg::replication_client::ReplicationClient,
    session: Option<ForeignSession>,
}

struct ForeignSessionPool {
    /// Serializes slot assignment so a transaction and endpoint cannot be
    /// installed in two slots while another slot is being released.
    assignment: Mutex<()>,
    slots: FixedVec<Mutex<ForeignSessionSlot>>,
}

pub(crate) struct ForeignClientGuard<'a> {
    slot: MutexGuard<'a, ForeignSessionSlot>,
}

impl core::ops::Deref for ForeignClientGuard<'_> {
    type Target = crate::pg::replication_client::ReplicationClient;

    fn deref(&self) -> &Self::Target {
        &self.slot.client
    }
}

impl core::ops::DerefMut for ForeignClientGuard<'_> {
    fn deref_mut(&mut self) -> &mut Self::Target {
        &mut self.slot.client
    }
}

impl ForeignClientGuard<'_> {
    pub(crate) fn activate(&mut self) {
        let session = self
            .slot
            .session
            .as_mut()
            .expect("foreign session was reserved before activation");
        assert!(!session.active);
        session.active = true;
    }
}

pub(crate) const fn foreign_session_slot_bytes() -> usize {
    size_of::<Mutex<ForeignSessionSlot>>()
}

struct ForeignStatementContext {
    transaction_id: u32,
    serializable: bool,
    savepoints: FixedVec<crate::util::StackStr<63>>,
}

pub(crate) struct ForeignStatementContextGuard<'a> {
    context: MutexGuard<'a, ForeignStatementContext>,
    transaction_id: u32,
}

impl ForeignStatementContextGuard<'_> {
    pub(crate) fn is_serializable(&self) -> bool {
        self.context.transaction_id == self.transaction_id && self.context.serializable
    }

    pub(crate) fn savepoints(&self) -> &[crate::util::StackStr<63>] {
        if self.context.transaction_id == self.transaction_id {
            self.context.savepoints.as_slice()
        } else {
            &[]
        }
    }
}

pub(crate) fn foreign_statement_context_workspace_bytes(config: &Config) -> usize {
    size_of::<Mutex<ForeignStatementContext>>().saturating_add(
        config
            .max_savepoints_per_transaction
            .saturating_mul(size_of::<crate::util::StackStr<63>>()),
    )
}

#[derive(Clone, Copy)]
struct ActiveTransactionIdentity {
    transaction_id: u32,
    connection_id: Option<i32>,
    assigned: bool,
}

#[derive(Clone, Copy)]
struct RecentTransactionStatus {
    transaction_id: u64,
    committed: bool,
}

struct TransactionIdentityState {
    active: FixedVec<ActiveTransactionIdentity>,
    recent: FixedVec<RecentTransactionStatus>,
    recent_cursor: usize,
    latest: u64,
}

impl TransactionIdentityState {
    /// PostgreSQL reserves identities 0-2 (invalid, bootstrap, frozen), which
    /// always read as committed; ordinary transactions start at 3.
    const FIRST_NORMAL: u64 = 3;

    fn next(&self) -> Result<u32, SqlError> {
        self.latest
            .max(Self::FIRST_NORMAL - 1)
            .checked_add(1)
            .and_then(|next| u32::try_from(next).ok())
            .ok_or_else(|| {
                sql_err!(
                    sqlstate::PROGRAM_LIMIT_EXCEEDED,
                    "transaction identity space is exhausted"
                )
            })
    }

    fn preflight_active(&self) -> Result<(), SqlError> {
        if self.active.len() == self.active.capacity() {
            Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "transaction identity registry exhausted"
            ))
        } else {
            Ok(())
        }
    }

    fn register(&mut self, transaction_id: u32, connection_id: i32) -> Result<(), SqlError> {
        if transaction_id == 0 {
            return Err(sql_err!(
                sqlstate::DATA_EXCEPTION,
                "zero transaction identity"
            ));
        }
        if self
            .active
            .iter()
            .any(|identity| identity.transaction_id == transaction_id)
        {
            return Ok(());
        }
        self.preflight_active()?;
        self.active
            .push(ActiveTransactionIdentity {
                transaction_id,
                connection_id: (connection_id > 0).then_some(connection_id),
                assigned: false,
            })
            .expect("transaction identity capacity was checked under its guard");
        self.latest = self.latest.max(u64::from(transaction_id));
        Ok(())
    }
}

