    pub(crate) fn empty_stored_query_dependencies(
        &self,
        arena: &crate::mem::arena::Arena,
    ) -> Result<StoredQueryDependencies, SqlError> {
        StoredQueryDependencies::with_arena_limit(self.stored_query_dependencies_per_image, arena)
            .map_err(|_| {
                sql_err!(
                    sqlstate::OUT_OF_MEMORY,
                    "SQL statement arena is full while capturing stored-query dependencies"
                )
            })
    }

    fn committed_dependency_image(&self, owner: StoredQueryDependencyOwner) -> usize {
        match owner {
            StoredQueryDependencyOwner::Rule(slot) => usize::from(slot),
            StoredQueryDependencyOwner::Policy(slot) => self.rule_count() + usize::from(slot),
            StoredQueryDependencyOwner::Routine(slot) => {
                self.rule_count() + self.policy_count() + usize::from(slot)
            }
            StoredQueryDependencyOwner::MaterializedView(slot) => {
                self.matview_dependency_image(usize::from(slot))
            }
        }
    }

    fn matview_dependency_image(&self, slot: usize) -> usize {
        self.rule_count() + self.policy_count() + self.routine_count() + slot
    }

    fn write_dependency_image_in(
        &self,
        catalog: &mut StoredQueryDependencyCatalog,
        image: usize,
        dependencies: StoredQueryDependencyView<'_>,
    ) -> Result<(), SqlError> {
        let count = catalog.write_image(
            image,
            dependencies,
            self.stored_query_dependencies_per_image,
        )?;
        catalog.counts[image] = count;
        Ok(())
    }

    fn clear_committed_dependencies(&self, owner: StoredQueryDependencyOwner) {
        let image = self.committed_dependency_image(owner);
        let mut catalog = self
            .stored_query_dependencies
            .lock()
            .expect("stored-query dependency catalog lock poisoned");
        catalog.counts[image] = 0;
        catalog.type_inputs[image] = StoredTypeInputs::EMPTY;
    }

    fn copy_dependency_image(&self, source_image: usize, target_image: usize) {
        self.stored_query_dependencies
            .lock()
            .expect("stored-query dependency catalog lock poisoned")
            .copy_image(
                source_image,
                target_image,
                self.stored_query_dependencies_per_image,
            );
    }

    fn with_dependency_image_mut<R>(
        &self,
        image: usize,
        mutate: impl FnOnce(&mut [StoredQueryDependency]) -> R,
    ) -> R {
        let mut catalog = self
            .stored_query_dependencies
            .lock()
            .expect("stored-query dependency catalog lock poisoned");
        let count = catalog.image_count(image);
        mutate(catalog.image_mut(image, count, self.stored_query_dependencies_per_image))
    }

    fn clear_dependency_image(&self, image: usize) {
        let mut catalog = self
            .stored_query_dependencies
            .lock()
            .expect("stored-query dependency catalog lock poisoned");
        catalog.counts[image] = 0;
        catalog.type_inputs[image] = StoredTypeInputs::EMPTY;
    }

    fn snapshot_dependency_image(
        &self,
        image: usize,
        arena: &crate::mem::arena::Arena,
    ) -> Result<StoredQueryDependencies, SqlError> {
        let catalog = self
            .stored_query_dependencies
            .lock()
            .expect("stored-query dependency catalog lock poisoned");
        let count = catalog.image_count(image);
        let source = catalog.image(image, count, self.stored_query_dependencies_per_image);
        let mut snapshot =
            StoredQueryDependencies::with_arena_limit(usize::from(count).max(1), arena).map_err(
                |_| {
                    sql_err!(
                        sqlstate::OUT_OF_MEMORY,
                        "SQL statement arena is full while copying stored-query dependencies"
                    )
                },
            )?;
        for dependency in source {
            snapshot.push(*dependency)?;
        }
        snapshot.type_inputs = catalog.type_inputs[image].clone();
        Ok(snapshot)
    }

    pub(crate) fn snapshot_view_dependencies(
        &self,
        slot: usize,
        txid: u32,
        arena: &crate::mem::arena::Arena,
    ) -> Result<StoredQueryDependencies, SqlError> {
        let catalog = self.view_rule_catalog();
        let rule_slot = catalog.views[slot].return_rule;
        let rule = catalog.rules[usize::from(rule_slot)];
        let image = rule
            .pending
            .filter(|pending| pending.txid == txid)
            .map_or_else(
                || self.committed_dependency_image(StoredQueryDependencyOwner::Rule(rule_slot)),
                |pending| {
                    self.stored_query_dependency_pending_base + pending.dependency_slot as usize
                },
            );
        self.snapshot_dependency_image(image, arena)
    }

    pub(crate) fn snapshot_matview_dependencies(
        &self,
        slot: usize,
        txid: u32,
        arena: &crate::mem::arena::Arena,
    ) -> Result<StoredQueryDependencies, SqlError> {
        let image = self
            .matview(slot)
            .pending_query
            .filter(|pending| pending.transaction == txid)
            .map_or_else(
                || self.matview_dependency_image(slot),
                |pending| {
                    self.stored_query_dependency_pending_base + pending.dependency_slot as usize
                },
            );
        self.snapshot_dependency_image(image, arena)
    }

    fn copy_committed_dependencies(
        &self,
        source: StoredQueryDependencyOwner,
        target: StoredQueryDependencyOwner,
    ) {
        self.copy_dependency_image(
            self.committed_dependency_image(source),
            self.committed_dependency_image(target),
        );
    }

    fn committed_dependencies(
        &self,
        owner: StoredQueryDependencyOwner,
    ) -> StoredQueryDependencyImage<'_> {
        let image = self.committed_dependency_image(owner);
        let catalog = self
            .stored_query_dependencies
            .lock()
            .expect("stored-query dependency catalog lock poisoned");
        let count = catalog.counts[image];
        StoredQueryDependencyImage {
            catalog,
            image,
            count,
            entries_per_image: self.stored_query_dependencies_per_image,
        }
    }

    fn allocate_pending_stored_query_dependencies_in(
        &self,
        catalog: &mut StoredQueryDependencyCatalog,
        owner: StoredQueryDependencyOwner,
        previous: Option<u32>,
        dependencies: StoredQueryDependencyView<'_>,
    ) -> Result<u32, SqlError> {
        if previous.is_some_and(|slot| {
            catalog.pending[slot as usize].depth >= self.max_catalog_versions_per_object
        }) {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "stored query exceeds max_catalog_versions_per_object ({})",
                self.max_catalog_versions_per_object
            ));
        }
        let Some(slot) = catalog.pending.iter().position(|pending| !pending.used) else {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "pending stored-query dependency pool is exhausted"
            ));
        };
        let depth = previous.map_or(1, |previous| catalog.pending[previous as usize].depth + 1);
        let image = self.stored_query_dependency_pending_base + slot;
        let count = catalog.write_image(
            image,
            dependencies,
            self.stored_query_dependencies_per_image,
        )?;
        catalog.pending[slot] = PendingStoredQueryDependencies {
            used: true,
            owner,
            previous,
            depth,
            count,
        };
        Ok(slot as u32)
    }

    fn allocate_pending_stored_query_dependencies_from_current_in(
        &self,
        catalog: &mut StoredQueryDependencyCatalog,
        owner: StoredQueryDependencyOwner,
        previous: Option<u32>,
    ) -> Result<u32, SqlError> {
        if previous.is_some_and(|slot| {
            catalog.pending[slot as usize].depth >= self.max_catalog_versions_per_object
        }) {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "stored query exceeds max_catalog_versions_per_object ({})",
                self.max_catalog_versions_per_object
            ));
        }
        let Some(slot) = catalog.pending.iter().position(|pending| !pending.used) else {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "pending stored-query dependency pool is exhausted"
            ));
        };
        let depth = previous.map_or(1, |previous| catalog.pending[previous as usize].depth + 1);
        let (source_image, count) = previous.map_or_else(
            || {
                let image = self.committed_dependency_image(owner);
                (image, catalog.counts[image])
            },
            |previous| {
                (
                    self.stored_query_dependency_pending_base + previous as usize,
                    catalog.pending[previous as usize].count,
                )
            },
        );
        let target_image = self.stored_query_dependency_pending_base + slot;
        let source = source_image * self.stored_query_dependencies_per_image;
        let target = target_image * self.stored_query_dependencies_per_image;
        catalog
            .entries
            .copy_within(source..source + usize::from(count), target);
        catalog.type_inputs[target_image] = catalog.type_inputs[source_image].clone();
        catalog.pending[slot] = PendingStoredQueryDependencies {
            used: true,
            owner,
            previous,
            depth,
            count,
        };
        Ok(slot as u32)
    }

    fn pending_dependencies(&self, slot: u32) -> StoredQueryDependencyImage<'_> {
        let catalog = self
            .stored_query_dependencies
            .lock()
            .expect("stored-query dependency catalog lock poisoned");
        let count = catalog.pending[slot as usize].count;
        StoredQueryDependencyImage {
            catalog,
            image: self.stored_query_dependency_pending_base + slot as usize,
            count,
            entries_per_image: self.stored_query_dependencies_per_image,
        }
    }

    fn release_pending_dependencies(&self, slot: u32) -> Option<u32> {
        let mut catalog = self
            .stored_query_dependencies
            .lock()
            .expect("stored-query dependency catalog lock poisoned");
        let pending = catalog.pending[slot as usize];
        catalog.pending[slot as usize] = PendingStoredQueryDependencies::EMPTY;
        catalog.type_inputs[self.stored_query_dependency_pending_base + slot as usize] =
            StoredTypeInputs::EMPTY;
        pending.previous
    }

    fn clear_pending_dependency_chain(&self, mut tail: Option<u32>) {
        while let Some(slot) = tail {
            tail = self.release_pending_dependencies(slot);
        }
    }

    fn commit_pending_dependencies(&self, owner: StoredQueryDependencyOwner, tail: u32) {
        let mut catalog = self
            .stored_query_dependencies
            .lock()
            .expect("stored-query dependency catalog lock poisoned");
        self.commit_pending_dependencies_in(&mut catalog, owner, tail);
    }

    fn commit_pending_dependencies_in(
        &self,
        catalog: &mut StoredQueryDependencyCatalog,
        owner: StoredQueryDependencyOwner,
        tail: u32,
    ) {
        let pending = catalog.pending[tail as usize];
        debug_assert_eq!(pending.owner, owner);
        let source_image = self.stored_query_dependency_pending_base + tail as usize;
        let target_image = self.committed_dependency_image(owner);
        let source = source_image * self.stored_query_dependencies_per_image;
        let target = target_image * self.stored_query_dependencies_per_image;
        catalog
            .entries
            .copy_within(source..source + usize::from(pending.count), target);
        catalog.counts[target_image] = pending.count;
        catalog.type_inputs[target_image] = catalog.type_inputs[source_image].clone();
        let mut next = Some(tail);
        while let Some(slot) = next {
            let pending = catalog.pending[slot as usize];
            catalog.pending[slot as usize] = PendingStoredQueryDependencies::EMPTY;
            catalog.type_inputs[self.stored_query_dependency_pending_base + slot as usize] =
                StoredTypeInputs::EMPTY;
            next = pending.previous;
        }
    }

    pub fn rebind_stored_query_dependencies(
        &self,
        serialized: StoredQueryDependencies,
        txid: u32,
    ) -> Result<StoredQueryDependencies, SqlError> {
        let mut rebound =
            StoredQueryDependencies::with_recovery_limit(self.stored_query_dependencies_per_image);
        for dependency in serialized.entries() {
            rebound.push(self.rebound_stored_query_dependency(*dependency, txid)?)?;
        }
        rebound.type_inputs = serialized.type_inputs.clone();
        Ok(rebound)
    }

    pub(crate) fn rebound_stored_query_dependency(
        &self,
        mut dependency: StoredQueryDependency,
        txid: u32,
    ) -> Result<StoredQueryDependency, SqlError> {
        if matches!(
            dependency.class,
            DependencyClass::Table | DependencyClass::View
        ) {
            return self.rebind_stored_query_relation(dependency, txid);
        }
        if matches!(
            dependency.class,
            DependencyClass::Domain | DependencyClass::Enum | DependencyClass::Composite
        ) {
            self.type_catalog
                .lock()
                .expect("type catalog lock poisoned")
                .bind_query_type_dependency(&mut dependency, txid)?;
            return Ok(dependency);
        }
        let schema = dependency.schema.as_str();
        let name = dependency.name.as_str();
        let slot = match dependency.class {
            DependencyClass::Table | DependencyClass::View => {
                unreachable!("relation source handled above")
            }
            DependencyClass::Domain | DependencyClass::Enum | DependencyClass::Composite => {
                unreachable!("type source handled above")
            }
            DependencyClass::Sequence => self.sequence_slot(schema, name, txid),
            DependencyClass::Routine => match dependency.identity {
                StoredDependencyIdentity::RoutineOid(oid) => self.routine_slot_by_oid(oid, txid),
                StoredDependencyIdentity::Name
                | StoredDependencyIdentity::Table(_)
                | StoredDependencyIdentity::View(_)
                | StoredDependencyIdentity::OperatorOid(_)
                | StoredDependencyIdentity::Type(_)
                | StoredDependencyIdentity::Collation(_)
                | StoredDependencyIdentity::TextSearchConfigurationOid(_) => None,
            },
            DependencyClass::Operator => match dependency.identity {
                StoredDependencyIdentity::OperatorOid(oid) => self.operator_slot_by_oid(oid, txid),
                StoredDependencyIdentity::Name
                | StoredDependencyIdentity::Table(_)
                | StoredDependencyIdentity::View(_)
                | StoredDependencyIdentity::RoutineOid(_)
                | StoredDependencyIdentity::Type(_)
                | StoredDependencyIdentity::Collation(_)
                | StoredDependencyIdentity::TextSearchConfigurationOid(_) => None,
            },
            DependencyClass::Collation => match dependency.identity {
                StoredDependencyIdentity::Collation(selected) => {
                    self.collations_visible_to(txid).find_map(|(slot, _)| {
                        (self.collation(slot).binding() == selected).then_some(slot)
                    })
                }
                _ => None,
            },
            DependencyClass::TextSearchConfiguration => match dependency.identity {
                StoredDependencyIdentity::TextSearchConfigurationOid(oid) => self
                    .text_search_slot_by_oid(
                        crate::sql::ast::TextSearchObjectKind::Configuration,
                        oid,
                        txid,
                    ),
                _ => None,
            },
        }
        .ok_or_else(|| {
            sql_err!(
                sqlstate::UNDEFINED_OBJECT,
                "stored-query dependency {}.{} does not exist",
                schema,
                name
            )
        })?;
        let (schema, name) = if dependency.class == DependencyClass::Collation {
            let definition = self.collation(slot).definition_for(txid);
            (definition.schema, definition.name)
        } else {
            (dependency.schema, dependency.name)
        };
        Ok(StoredQueryDependency {
            class: dependency.class,
            slot: slot as u16,
            identity: dependency.identity,
            referenced_columns: dependency.referenced_columns,
            written_columns: dependency.written_columns,
            schema,
            name,
            referenced_schema: dependency.referenced_schema,
            referenced_name: dependency.referenced_name,
        })
    }

    fn rebind_stored_query_dependency_image(
        &mut self,
        image: usize,
        txid: u32,
        template_source: Option<DatabaseOid>,
    ) -> Result<(), SqlError> {
        // Resolve identities without retaining the dependency mutex: catalog
        // publication writes dependencies while holding its definition guard.
        let mut snapshot = [StoredQueryDependency::EMPTY; MAX_STORED_QUERY_DEPENDENCIES];
        let (count, inputs) = {
            let catalog = self
                .stored_query_dependencies
                .lock()
                .expect("stored-query dependency catalog lock poisoned");
            let count = catalog.image_count(image);
            snapshot[..usize::from(count)].copy_from_slice(catalog.image(
                image,
                count,
                self.stored_query_dependencies_per_image,
            ));
            (count, catalog.type_inputs[image].clone())
        };
        if let Some(source) = template_source {
            self.validate_template_type_inputs(&inputs, source, txid)?;
        }
        let dependencies = &mut snapshot[..usize::from(count)];
        for dependency in dependencies.iter_mut() {
            if let Some(source) = template_source {
                self.clone_stored_query_relation(dependency, source)?;
                self.type_catalog
                    .lock()
                    .expect("type catalog lock poisoned")
                    .clone_query_type_dependency(dependency, source, txid)?;
            }
            *dependency = self.rebound_stored_query_dependency(*dependency, txid)?;
        }
        let mut catalog = self
            .stored_query_dependencies
            .lock()
            .expect("stored-query dependency catalog lock poisoned");
        catalog
            .image_mut(image, count, self.stored_query_dependencies_per_image)
            .copy_from_slice(dependencies);
        Ok(())
    }

    pub fn rebind_all_stored_query_dependencies(
        &mut self,
        transaction: u32,
    ) -> Result<(), SqlError> {
        self.rebind_all_stored_query_dependencies_to(transaction, None)
    }

    fn rebind_all_stored_query_dependencies_to(
        &mut self,
        txid: u32,
        template_source: Option<DatabaseOid>,
    ) -> Result<(), SqlError> {
        for slot in 0..self.rule_count() {
            let rule = self.rule(slot);
            let pending = rule.pending.filter(|pending| pending.txid == txid);
            if rule.database == current_database()
                && rule.visible_to(txid)
                && (txid == 0
                    || pending.is_some()
                    || rule.ddl_state == (CatalogDdlState::PendingCreate { txid }))
            {
                let owner = StoredQueryDependencyOwner::Rule(slot as u16);
                let image = pending.map_or_else(
                    || self.committed_dependency_image(owner),
                    |pending| {
                        self.stored_query_dependency_pending_base + pending.dependency_slot as usize
                    },
                );
                self.rebind_stored_query_dependency_image(image, txid, template_source)?;
            }
        }
        for slot in 0..self.matview_count() {
            let definition = self.matview(slot);
            let pending = definition
                .pending_query
                .filter(|pending| pending.transaction == txid);
            if definition.database == current_database()
                && definition.visible_to(txid)
                && (txid == 0
                    || pending.is_some()
                    || definition.ddl_state == (CatalogDdlState::PendingCreate { txid }))
            {
                let image = pending.map_or_else(
                    || self.matview_dependency_image(slot),
                    |pending| {
                        self.stored_query_dependency_pending_base + pending.dependency_slot as usize
                    },
                );
                self.rebind_stored_query_dependency_image(image, txid, template_source)?;
            }
        }
        for slot in 0..self.policy_count() {
            let policy = self.policy(slot);
            let pending = policy
                .pending_definition
                .filter(|pending| pending.txid == txid);
            if policy.database == current_database()
                && policy.visible_to(txid)
                && (txid == 0
                    || pending.is_some()
                    || policy.ddl_state == (CatalogDdlState::PendingCreate { txid }))
            {
                let owner = StoredQueryDependencyOwner::Policy(slot as u16);
                let image = pending.map_or_else(
                    || self.committed_dependency_image(owner),
                    |pending| {
                        self.stored_query_dependency_pending_base + pending.dependency_slot as usize
                    },
                );
                self.rebind_stored_query_dependency_image(image, txid, template_source)?;
            }
        }
        for slot in 0..self.routine_count() {
            let routine = self.routine(slot);
            let pending = routine
                .pending_definition
                .filter(|pending| pending.txid == txid);
            if routine.database == current_database()
                && routine.visible_to(txid)
                && (txid == 0
                    || pending.is_some()
                    || routine.ddl_state == (CatalogDdlState::PendingCreate { txid }))
            {
                let owner = StoredQueryDependencyOwner::Routine(slot as u16);
                let image = pending.map_or_else(
                    || self.committed_dependency_image(owner),
                    |pending| {
                        self.stored_query_dependency_pending_base + pending.dependency_slot as usize
                    },
                );
                self.rebind_stored_query_dependency_image(image, txid, template_source)?;
            }
        }
        Ok(())
    }

    fn rename_stored_query_dependency(
        &self,
        class: DependencyClass,
        slot: usize,
        old_identity: Option<(SqlName, SqlName)>,
        schema: SqlName,
        name: SqlName,
    ) {
        let mut catalog = self
            .stored_query_dependencies
            .lock()
            .expect("stored-query dependency catalog lock poisoned");
        self.rename_stored_query_dependency_locked(
            &mut catalog,
            class,
            slot,
            old_identity,
            schema,
            name,
        );
    }

    fn rename_stored_query_dependency_locked(
        &self,
        catalog: &mut StoredQueryDependencyCatalog,
        class: DependencyClass,
        slot: usize,
        old_identity: Option<(SqlName, SqlName)>,
        schema: SqlName,
        name: SqlName,
    ) {
        for image in 0..catalog.counts.len() {
            let count = catalog.counts[image];
            rename_dependency(
                catalog.image_mut(image, count, self.stored_query_dependencies_per_image),
                class,
                slot,
                old_identity,
                schema,
                name,
            );
        }
        for pending_slot in 0..catalog.pending.len() {
            let pending = catalog.pending[pending_slot];
            if pending.used {
                let image = self.stored_query_dependency_pending_base + pending_slot;
                rename_dependency(
                    catalog.image_mut(
                        image,
                        pending.count,
                        self.stored_query_dependencies_per_image,
                    ),
                    class,
                    slot,
                    old_identity,
                    schema,
                    name,
                );
            }
        }
    }

    /// Bytes drawn beyond the row heap itself, for the memory plan.
    pub(crate) fn table_definition_image_budget_bytes(config: &Config) -> usize {
        definition_images::TableDefinitionImagePool::budget_bytes(config)
    }

    pub(crate) fn type_definition_image_budget_bytes(config: &Config) -> usize {
        type_definitions::TypeDefinitionImagePools::budget_bytes(config)
    }

    pub(crate) fn retained_spill_root_capacity(config: &Config) -> usize {
        SpillRootRegistry::capacity(config)
    }

    pub(crate) fn retained_index_file_capacity(config: &Config) -> usize {
        SpillRootRegistry::index_capacity(config)
    }

    pub(crate) fn copy_retained_index_roots(
        &self,
        output: &mut Vec<crate::store::BlockId>,
    ) -> Result<(), SqlError> {
        self.spill_roots.copy_index_roots(output)
    }

    pub(crate) fn copy_retained_spill_roots(
        &self,
        durable: bool,
        output: &mut Vec<crate::store::SstHandle>,
    ) -> Result<(), SqlError> {
        self.spill_roots.copy_roots(durable, output)
    }

    pub(crate) fn retained_file_reclamation_pending(&self) -> bool {
        self.spill_roots.reclamation_pending()
    }
    pub(crate) fn take_retained_file_reclamation(&self) -> bool {
        self.spill_roots.take_reclamation_pending()
    }

